public async Task AppendVersionAsync(MemoryEntity entity, CancellationToken cancellationToken)
    {
        var nextNumber = await NextVersionNumberAsync(entity.Id, cancellationToken).ConfigureAwait(false);
        _db.MemoryVersions.Add(new MemoryVersionEntity
        {
            MemoryId = entity.Id,
            VersionNumber = nextNumber,
            Title = entity.Title,
            Content = MemoryLayerMapper.EffectiveContent(entity),
            CreatedAtUtc = entity.UpdatedAtUtc,
        });
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }

public async Task<MemoryRevertResult> RevertAsync(
        string memoryId,
        int versionNumber,
        bool readOnlyCaller,
        CancellationToken cancellationToken)
    {
        if (readOnlyCaller)
            return new MemoryRevertResult(403, FailureKind: MemoryMutationFailureKind.Validation, Error: "Read-only caller cannot revert.");

        var entity = await _db.Memories
            .FirstOrDefaultAsync(memory => memory.Id == memoryId, cancellationToken)
            .ConfigureAwait(false);
        if (entity is null)
            return new MemoryRevertResult(404, FailureKind: MemoryMutationFailureKind.NotFound, Error: $"Memory '{memoryId}' not found.");

        var snapshot = await _db.MemoryVersions
            .AsNoTracking()
            .FirstOrDefaultAsync(
                version => version.MemoryId == memoryId && version.VersionNumber == versionNumber,
                cancellationToken)
            .ConfigureAwait(false);
        if (snapshot is null)
            return new MemoryRevertResult(404, FailureKind: MemoryMutationFailureKind.NotFound, Error: $"Version {versionNumber} was not found.");

        entity.Title = snapshot.Title;
        entity.Content = snapshot.Content;
        entity.Text = snapshot.Content;
        entity.Version++;
        entity.UpdatedAtUtc = DateTimeOffset.UtcNow;
        entity.EmbeddingStatus = "pending";

        var nextNumber = await NextVersionNumberAsync(memoryId, cancellationToken).ConfigureAwait(false);
        _db.MemoryVersions.Add(new MemoryVersionEntity
        {
            MemoryId = entity.Id,
            VersionNumber = nextNumber,
            Title = entity.Title,
            Content = MemoryLayerMapper.EffectiveContent(entity),
            CreatedAtUtc = entity.UpdatedAtUtc,
        });

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await MemorySessionLogHook.TryAppendAsync(_db, entity.Id, "memory_revert", cancellationToken).ConfigureAwait(false);
        return new MemoryRevertResult(200, MemoryLayerMapper.ToItem(entity));
    }

private async Task<MemoryConsolidateResult> ConsolidateUnlockedAsync(
        bool dryRun,
        string runId,
        CancellationToken cancellationToken)
    {
        var memories = await _db.Memories
            .Where(m => m.WorkspaceId == _workspacePath)
            .Where(m => m.Scope == MemoryEntity.WorkspaceScope)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);

        var clusters = BuildClusters(memories, MemoryConsolidateLimits.DefaultSimilarityThreshold);
        var plan = clusters.Select(c => new MemoryConsolidatePlanItem
        {
            CandidateIds = c.Select(m => m.Id).ToList(),
            SimilarityScore = ScoreCluster(c),
            SurvivorId = dryRun ? null : PickSurvivor(c).Id,
        }).ToList();

        if (dryRun)
            return new MemoryConsolidateResult(200, Plan: plan, RunId: runId, DryRunApplied: true, EventEmitted: false);

        string? survivorId = null;
        var mergedAway = new List<string>();
        foreach (var cluster in clusters)
        {
            var survivor = PickSurvivor(cluster);
            survivorId = survivor.Id;
            var nextVersion = await _db.MemoryVersions
                .Where(v => v.MemoryId == survivor.Id)
                .Select(v => (int?)v.VersionNumber)
                .MaxAsync(cancellationToken)
                .ConfigureAwait(false) ?? survivor.Version;
            nextVersion += 1;
            foreach (var victim in cluster.Where(m => m.Id != survivor.Id))
            {
                nextVersion = AppendLineage(survivor, victim, nextVersion);
                await RewireEdgesAsync(survivor.Id, victim.Id, cancellationToken).ConfigureAwait(false);
                _db.Memories.Remove(victim);
                mergedAway.Add(victim.Id);
            }
        }

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return new MemoryConsolidateResult(
            200,
            Plan: plan,
            SurvivorId: survivorId,
            MergedAwayIds: mergedAway,
            RunId: runId,
            DryRunApplied: false,
            EventEmitted: true);
    }

