public async Task<MemoryCreateEdgeResult> CreateEdgeAsync(
        MemoryCreateEdgeRequest? request,
        bool readOnlyCaller,
        CancellationToken cancellationToken)
    {
        if (readOnlyCaller)
        {
            return new MemoryCreateEdgeResult(
                403,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "Read-only caller cannot create memory edges.");
        }

        if (request is null)
        {
            return new MemoryCreateEdgeResult(
                400,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "Request body is required.");
        }

        var fromId = NormalizeOptional(request.FromMemoryId);
        var toId = NormalizeOptional(request.ToMemoryId);
        if (fromId is null || toId is null)
        {
            return new MemoryCreateEdgeResult(
                400,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "FromMemoryId and ToMemoryId are required.");
        }

        if (string.Equals(fromId, toId, StringComparison.Ordinal))
        {
            return new MemoryCreateEdgeResult(
                MemoryExploreLimits.SelfLoopStatusCode,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "Self-loop edges are not allowed.");
        }

        var edgeType = NormalizeEdgeType(request.EdgeType);
        if (edgeType is null || !MemoryExploreLimits.AllowedEdgeTypes.Contains(edgeType))
        {
            return new MemoryCreateEdgeResult(
                400,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "EdgeType is not an allowed memory edge type.");
        }

        var weight = request.Weight ?? MemoryExploreLimits.MaxWeight;
        if (weight < MemoryExploreLimits.MinWeight || weight > MemoryExploreLimits.MaxWeight)
        {
            return new MemoryCreateEdgeResult(
                400,
                FailureKind: MemoryMutationFailureKind.Validation,
                Error: "Weight must be in [0,1].");
        }

        var visibleIds = await LoadVisibleIdsAsync(cancellationToken).ConfigureAwait(false);
        if (!visibleIds.Contains(fromId) || !visibleIds.Contains(toId))
        {
            return new MemoryCreateEdgeResult(
                404,
                FailureKind: MemoryMutationFailureKind.NotFound,
                Error: "Edge endpoints must be visible in the caller Effective set.");
        }

        var exists = await _db.MemoryEdges.AnyAsync(
            edge => edge.FromMemoryId == fromId && edge.ToMemoryId == toId && edge.EdgeType == edgeType,
            cancellationToken).ConfigureAwait(false);
        if (exists)
        {
            return new MemoryCreateEdgeResult(
                MemoryExploreLimits.DuplicateExplicitStatusCode,
                FailureKind: MemoryMutationFailureKind.Conflict,
                Error: "An edge with the same From, To, and EdgeType already exists.");
        }

        var entity = new MemoryEdgeEntity
        {
            FromMemoryId = fromId,
            ToMemoryId = toId,
            EdgeType = edgeType,
            Weight = weight,
        };
        _db.MemoryEdges.Add(entity);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return new MemoryCreateEdgeResult(
            201,
            new MemoryEdgeRecord
            {
                FromMemoryId = entity.FromMemoryId,
                ToMemoryId = entity.ToMemoryId,
                EdgeType = entity.EdgeType,
                Weight = entity.Weight,
            });
    }

public async Task<MemoryHebbianResult> RecordHebbianAsync(
        IReadOnlyList<string>? memoryIds,
        bool hebbianEnabled,
        CancellationToken cancellationToken)
    {
        if (!hebbianEnabled)
        {
            return new MemoryHebbianResult(200, [], RankingUnchanged: true);
        }

        var visibleIds = await LoadVisibleIdsAsync(cancellationToken).ConfigureAwait(false);
        var ids = (memoryIds ?? [])
            .Select(NormalizeOptional)
            .Where(id => id is not null && visibleIds.Contains(id))
            .Cast<string>()
            .Distinct(StringComparer.Ordinal)
            .ToList();
        if (ids.Count < 2)
            return new MemoryHebbianResult(200, [], RankingUnchanged: true);

        var created = new List<MemoryEdgeRecord>();
        for (var i = 0; i < ids.Count; i++)
        {
            for (var j = 0; j < ids.Count; j++)
            {
                if (i == j)
                    continue;

                var record = await StrengthenCoRetrievedAsync(ids[i], ids[j], cancellationToken)
                    .ConfigureAwait(false);
                created.Add(record);
            }
        }

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return new MemoryHebbianResult(201, created, RankingUnchanged: true);
    }

public async Task<MemoryIndexResult> IndexAsync(
        string memoryId,
        string? provider,
        bool cloudEnabled,
        CancellationToken cancellationToken)
    {
        if (cancellationToken.IsCancellationRequested)
        {
            var current = await ReadStatusAsync(memoryId, CancellationToken.None).ConfigureAwait(false);
            return new MemoryIndexResult(
                200,
                memoryId,
                current is "ready" ? "pending" : current ?? "pending");
        }

        var entity = await _db.Memories
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(memory => memory.Id == memoryId, cancellationToken)
            .ConfigureAwait(false);
        if (entity is null)
        {
            return new MemoryIndexResult(
                404,
                memoryId,
                Error: $"Memory '{memoryId}' not found.");
        }

        var content = MemoryLayerMapper.EffectiveContent(entity);
        if (string.IsNullOrWhiteSpace(content))
        {
            if (string.Equals(entity.EmbeddingStatus, "ready", StringComparison.OrdinalIgnoreCase))
                entity.EmbeddingStatus = "pending";
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return new MemoryIndexResult(
                400,
                memoryId,
                entity.EmbeddingStatus ?? "pending",
                Error: "Content is required.");
        }

        if (string.Equals(provider, "cloud", StringComparison.OrdinalIgnoreCase) && !cloudEnabled)
        {
            entity.EmbeddingStatus = "failed";
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return new MemoryIndexResult(
                200,
                memoryId,
                "failed",
                FailureReason: "Cloud embedding is disabled.");
        }

        cancellationToken.ThrowIfCancellationRequested();

        var hash = ComputeContentHash(entity);
        var embedding = MemoryLocalEmbedding.Embed(BuildSearchableText(entity));
        var existing = await _db.MemoryIndexes
            .IgnoreQueryFilters()
            .FirstOrDefaultAsync(index => index.MemoryId == memoryId, cancellationToken)
            .ConfigureAwait(false);
        if (existing is null)
        {
            _db.MemoryIndexes.Add(new MemoryIndexEntity
            {
                MemoryId = entity.Id,
                WorkspaceId = entity.WorkspaceId,
                ContentHash = hash,
                EmbeddingJson = MemoryLocalEmbedding.Serialize(embedding),
                IndexedAtUtc = DateTimeOffset.UtcNow,
            });
        }
        else
        {
            existing.WorkspaceId = entity.WorkspaceId;
            existing.ContentHash = hash;
            existing.EmbeddingJson = MemoryLocalEmbedding.Serialize(embedding);
            existing.IndexedAtUtc = DateTimeOffset.UtcNow;
        }

        entity.EmbeddingStatus = "ready";
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return new MemoryIndexResult(200, memoryId, "ready", ReadyCount: 1);
    }

public static async Task TryAppendAsync(
        McpDbContext db,
        string memoryId,
        string actionType,
        CancellationToken cancellationToken)
    {
        var workspaceId = db.CurrentWorkspaceId;
        var turn = await (
                from entry in db.SessionLogTurns.IgnoreQueryFilters()
                join session in db.SessionLogs.IgnoreQueryFilters() on entry.SessionLogId equals session.Id
                where session.WorkspaceId == workspaceId || entry.WorkspaceId == workspaceId
                orderby entry.Id descending
                select entry)
            .FirstOrDefaultAsync(cancellationToken)
            .ConfigureAwait(false);
        if (turn is null)
            return;

        var order = await db.SessionLogActions
            .IgnoreQueryFilters()
            .CountAsync(action => action.SessionLogTurnId == turn.Id, cancellationToken)
            .ConfigureAwait(false);

        db.SessionLogActions.Add(new SessionLogActionEntity
        {
            WorkspaceId = string.IsNullOrEmpty(turn.WorkspaceId) ? workspaceId : turn.WorkspaceId,
            SessionLogTurnId = turn.Id,
            Order = order + 1,
            Type = "memory",
            Status = "completed",
            Description = $"{actionType} {memoryId}",
        });
        await db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }

private static void UpsertTraceabilityLink(
        McpDbContext ctx,
        IReadOnlyList<RequirementTraceabilityLinkEntity> existingLinks,
        string workspaceId,
        string frId,
        string targetKind,
        string targetId,
        string createdAtUtc)
    {
        var existing = existingLinks.FirstOrDefault(link =>
            string.Equals(link.TargetKind, targetKind, StringComparison.OrdinalIgnoreCase)
            && string.Equals(link.TargetId, targetId, StringComparison.OrdinalIgnoreCase));

        if (existing is null)
        {
            ctx.RequirementTraceabilityLinks.Add(new RequirementTraceabilityLinkEntity
            {
                WorkspaceId = workspaceId,
                FrId = frId,
                TargetKind = targetKind,
                TargetId = targetId,
                CreatedAtUtc = createdAtUtc
            });
            return;
        }

        existing.SourceKind = FrKind;
        if (IsSoftDeleted(ctx, existing))
        {
            existing.CreatedAtUtc = createdAtUtc;
            ClearSoftDelete(ctx, existing);
        }
    }

