public async Task UpsertAsync(string workspacePath, string accessToken, DateTimeOffset? expiresAtUtc = null, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(accessToken))
            throw new ArgumentException("Access token is required.", nameof(accessToken));

        var normalized = NormalizeWorkspacePath(workspacePath);
        var now = DateTimeOffset.UtcNow;
        var encrypted = _protector.Protect(accessToken.Trim());

        await _gate.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            using var storeLock = await AcquireStoreLockAsync(ct).ConfigureAwait(false);
            var doc = await ReadUnlockedAsync(ct).ConfigureAwait(false);
            var existing = doc.Entries.FirstOrDefault(e => string.Equals(e.WorkspacePath, normalized, StringComparison.OrdinalIgnoreCase));
            if (existing is null)
            {
                doc.Entries.Add(new GitHubTokenStoreEntry
                {
                    WorkspacePath = normalized,
                    AccessTokenProtected = encrypted,
                    UpdatedAtUtc = now,
                    ExpiresAtUtc = expiresAtUtc,
                });
            }
            else
            {
                existing.AccessTokenProtected = encrypted;
                existing.UpdatedAtUtc = now;
                existing.ExpiresAtUtc = expiresAtUtc;
            }

            await WriteUnlockedAsync(doc, ct).ConfigureAwait(false);
        }
        finally
        {
            _gate.Release();
        }
    }

public async Task RebuildAsync(CancellationToken ct = default)
    {
        if (!_isSqliteProvider)
        {
            _logger.LogInformation(
                "Skipping FTS5 rebuild for non-SQLite provider: {ProviderName}",
                _db.Database.ProviderName ?? "<unknown>");
            return;
        }

        try
        {
            var conn = _db.Database.GetDbConnection();
            await conn.OpenAsync(ct).ConfigureAwait(false);

            // Repopulate FTS5 index from visible chunks only. FTS SQL bypasses EF query
            // filters, so soft-delete predicates must be explicit here.
            using var deleteCmd = conn.CreateCommand();
            deleteCmd.CommandText = "DELETE FROM chunks_fts";
            await deleteCmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);

            using var insertCmd = conn.CreateCommand();
            insertCmd.CommandText = """
                INSERT INTO chunks_fts(ChunkId, Content)
                SELECT c.Id, c.Content
                FROM Chunks c
                JOIN Documents d ON c.DocumentId = d.Id
                WHERE c.IsDeleted = 0 AND d.IsDeleted = 0
                """;
            await insertCmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);

            using var rebuildCmd = conn.CreateCommand();
            rebuildCmd.CommandText = "INSERT INTO chunks_fts(chunks_fts) VALUES('rebuild')";
            await rebuildCmd.ExecuteNonQueryAsync(ct).ConfigureAwait(false);

            _logger.LogInformation("FTS5 index rebuilt successfully");
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            _logger.LogError(ex, "Failed to rebuild FTS5 index");
            throw;
        }
    }

private async Task<bool> TryCompleteApprovalAsync(
        HandoffIngestionRunEntity entity,
        string reviewState,
        bool succeeded,
        string? createdTodoId,
        string? reviewer,
        string? notes,
        string? error,
        string? errorCode,
        CancellationToken cancellationToken)
    {
        var version = entity.StateVersion;
        var updated = await _db.HandoffIngestionRuns
            .Where(run => run.RunId == entity.RunId
                && run.ApprovalOwner == _instanceId
                && run.StateVersion == version)
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.ReviewState, reviewState)
                    .SetProperty(run => run.ProcessingState, reviewState == nameof(HandoffReviewState.PendingReview)
                        ? nameof(HandoffProcessingState.None)
                        : nameof(HandoffProcessingState.Terminal))
                    .SetProperty(run => run.ApprovalOwner, (string?)null)
                    .SetProperty(run => run.ApprovalLeaseExpiresAtUtc, (DateTimeOffset?)null)
                    .SetProperty(run => run.CreatedTodoId, createdTodoId)
                    .SetProperty(run => run.Reviewer, reviewer)
                    .SetProperty(run => run.ReviewNotes, notes)
                    .SetProperty(run => run.Succeeded, succeeded)
                    .SetProperty(run => run.Error, SanitizeText(error))
                    .SetProperty(run => run.ErrorCode, errorCode)
                    .SetProperty(run => run.StateVersion, version + 1),
                cancellationToken)
            .ConfigureAwait(false);
        if (updated == 0)
            return false;

        entity.ReviewState = reviewState;
        entity.Succeeded = succeeded;
        entity.CreatedTodoId = createdTodoId;
        entity.Reviewer = reviewer;
        entity.ReviewNotes = notes;
        entity.Error = SanitizeText(error);
        entity.ErrorCode = errorCode;
        entity.StateVersion = version + 1;
        entity.ApprovalOwner = null;
        entity.ApprovalLeaseExpiresAtUtc = null;
        return true;
    }

private async Task<HandoffIngestionResult> ApproveCoreAsync(
        string runId,
        HandoffApprovalRequest request,
        CancellationToken cancellationToken)
    {
        var entity = await _db.HandoffIngestionRuns
            .Include(run => run.Diagnostics)
            .FirstOrDefaultAsync(run => run.RunId == runId, cancellationToken)
            .ConfigureAwait(false);

        if (entity is null)
            return new HandoffIngestionResult { Success = false, Error = $"Handoff run '{runId}' was not found.", ErrorCode = "run_not_found" };

        if (entity.ReviewState == nameof(HandoffReviewState.Created) && !string.IsNullOrWhiteSpace(entity.CreatedTodoId))
            return MapEntity(entity, replayed: true);

        if (entity.ReviewState == nameof(HandoffReviewState.Failed))
            return new HandoffIngestionResult { Success = false, Error = "Failed runs cannot be approved.", ErrorCode = "run_not_approvable" };

        var now = _time.GetUtcNow();
        var claimed = await _db.HandoffIngestionRuns
            .Where(run => run.RunId == runId
                && (run.ReviewState == nameof(HandoffReviewState.PendingReview)
                    || (run.ReviewState == nameof(HandoffReviewState.Approving)
                        && (run.ApprovalLeaseExpiresAtUtc == null || run.ApprovalLeaseExpiresAtUtc < now))))
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.ReviewState, nameof(HandoffReviewState.Approving))
                    .SetProperty(run => run.ApprovalOwner, _instanceId)
                    .SetProperty(run => run.ApprovalLeaseExpiresAtUtc, now.Add(_lease.Duration))
                    .SetProperty(run => run.StateVersion, run => run.StateVersion + 1),
                cancellationToken)
            .ConfigureAwait(false);

        if (claimed == 0)
        {
            entity = await _db.HandoffIngestionRuns
                .Include(run => run.Diagnostics)
                .FirstOrDefaultAsync(run => run.RunId == runId, cancellationToken)
                .ConfigureAwait(false);
            if (entity is null)
                return new HandoffIngestionResult { Success = false, Error = $"Handoff run '{runId}' was not found.", ErrorCode = HandoffErrorCodes.RunNotFound };
            if (entity.ReviewState == nameof(HandoffReviewState.Created) && !string.IsNullOrWhiteSpace(entity.CreatedTodoId))
                return MapEntity(entity, replayed: true);
            if (entity.ReviewState == nameof(HandoffReviewState.Approving) && entity.ApprovalLeaseExpiresAtUtc >= now)
                return InProgressResult(entity);
            return new HandoffIngestionResult { Success = false, Error = "Only pending-review runs can be approved.", ErrorCode = HandoffErrorCodes.RunNotApprovable };
        }

        _db.Entry(entity).State = EntityState.Detached;
        entity = await _db.HandoffIngestionRuns
            .Include(run => run.Diagnostics)
            .FirstAsync(run => run.RunId == runId, cancellationToken)
            .ConfigureAwait(false);

        if (!request.Approved)
        {
            if (!await TryCompleteApprovalAsync(
                    entity,
                    nameof(HandoffReviewState.Rejected),
                    succeeded: true,
                    createdTodoId: null,
                    SanitizeText(request.Reviewer),
                    SanitizeText(request.Notes),
                    error: null,
                    errorCode: null,
                    cancellationToken).ConfigureAwait(false))
            {
                return LostOwnershipResult(entity);
            }

            return MapEntity(entity, replayed: false);
        }

        var draft = string.IsNullOrWhiteSpace(entity.DraftJson)
            ? null
            : JsonSerializer.Deserialize<HandoffTodoDraft>(entity.DraftJson, DraftJsonOptions);
        var validation = _validator.Validate(draft);
        var diagnostics = validation.Diagnostics.ToList();
        await AddMissingReferenceDiagnosticsAsync(validation.Draft, diagnostics, cancellationToken).ConfigureAwait(false);
        if (!validation.IsValid || validation.Draft is null || diagnostics.Any(item => item.Severity == HandoffDiagnosticSeverity.Error))
        {
            diagnostics.Add(new HandoffDiagnostic
            {
                Code = "approval_invalid",
                Severity = HandoffDiagnosticSeverity.Error,
                Message = "Approval revalidation failed. The stored draft cannot create a TODO.",
            });
            ReplaceDiagnostics(entity, diagnostics);
            if (!await TryCompleteApprovalAsync(
                    entity,
                    nameof(HandoffReviewState.Failed),
                    succeeded: false,
                    createdTodoId: null,
                    SanitizeText(request.Reviewer),
                    SanitizeText(request.Notes),
                    "Approval revalidation failed.",
                    "approval_invalid",
                    cancellationToken).ConfigureAwait(false))
            {
                return LostOwnershipResult(entity);
            }
            var failed = MapEntity(entity, replayed: false);
            failed.Success = false;
            failed.Error = "Approval revalidation failed.";
            failed.ErrorCode = "approval_invalid";
            return failed;
        }

        var create = await TryCreateTodoAsync(entity, validation.Draft, diagnostics, cancellationToken).ConfigureAwait(false);
        if (!create.Created)
        {
            if (entity.ReviewState == nameof(HandoffReviewState.Created))
                return MapEntity(entity, replayed: true);

            var error = diagnostics.LastOrDefault(item => item.Severity == HandoffDiagnosticSeverity.Error);
            ReplaceDiagnostics(entity, diagnostics);
            if (!await TryCompleteApprovalAsync(
                    entity,
                    nameof(HandoffReviewState.PendingReview),
                    succeeded: false,
                    createdTodoId: null,
                    SanitizeText(request.Reviewer),
                    SanitizeText(request.Notes),
                    error?.Message,
                    error?.Code ?? HandoffErrorCodes.TodoCreateFailed,
                    cancellationToken).ConfigureAwait(false))
            {
                return LostOwnershipResult(entity);
            }
            var blocked = MapEntity(entity, replayed: false);
            blocked.RequiresReview = true;
            blocked.Success = false;
            blocked.Error = entity.Error;
            blocked.ErrorCode = entity.ErrorCode;
            return blocked;
        }

        ReplaceDiagnostics(entity, diagnostics);
        if (!await TryCompleteApprovalAsync(
                entity,
                nameof(HandoffReviewState.Created),
                succeeded: true,
                create.TodoId,
                SanitizeText(request.Reviewer),
                SanitizeText(request.Notes),
                error: null,
                errorCode: null,
                cancellationToken).ConfigureAwait(false))
        {
            return LostOwnershipResult(entity);
        }
        var created = MapEntity(entity, replayed: false);
        created.Created = true;
        return created;
    }

private async Task<(bool Created, string? TodoId)> TryCreateTodoAsync(
        HandoffIngestionRunEntity entity,
        HandoffTodoDraft draft,
        List<HandoffDiagnostic> diagnostics,
        CancellationToken cancellationToken)
    {
        var intentId = entity.TodoCreationIntentId;
        if (string.IsNullOrWhiteSpace(intentId))
        {
            intentId = $"handoff-todo:{entity.RunId}";
            using var persistCts = CreateCompensationCts();
            var version = entity.StateVersion;
            var persisted = await _db.HandoffIngestionRuns
                .Where(run => run.RunId == entity.RunId
                    && (run.ProcessingOwner == _instanceId || run.ApprovalOwner == _instanceId)
                    && run.StateVersion == version)
                .ExecuteUpdateAsync(
                    setters => setters
                        .SetProperty(run => run.TodoCreationIntentId, intentId)
                        .SetProperty(run => run.StateVersion, version + 1),
                    persistCts.Token)
                .ConfigureAwait(false);
            if (persisted == 0)
                return (false, null);
            entity.TodoCreationIntentId = intentId;
            entity.StateVersion = version + 1;
        }

        var todoService = _workspaceAccessor.GetTodoService();
        using var lookupCts = CreateCompensationCts();
        var existing = await todoService.GetByIdAsync(draft.Id!, lookupCts.Token).ConfigureAwait(false);
        if (existing is not null)
        {
            if (IsHeal(existing, intentId, draft))
                return (true, existing.Id);

            diagnostics.Add(CollisionDiagnostic());
            return (false, null);
        }

        try
        {
            var result = await todoService.CreateAsync(ToCreateRequest(draft, intentId), cancellationToken).ConfigureAwait(false);

            if (!result.Success)
            {
                using var conflictCts = CreateCompensationCts();
                var afterConflict = await todoService.GetByIdAsync(draft.Id!, conflictCts.Token).ConfigureAwait(false);
                if (afterConflict is not null && IsHeal(afterConflict, intentId, draft))
                    return (true, afterConflict.Id);

                diagnostics.Add(new HandoffDiagnostic
                {
                    Code = result.FailureKind == TodoMutationFailureKind.Conflict ? HandoffErrorCodes.TodoCollision : HandoffErrorCodes.TodoCreateFailed,
                    Severity = HandoffDiagnosticSeverity.Error,
                    Field = result.FailureKind == TodoMutationFailureKind.Conflict ? "id" : null,
                    Message = result.Error ?? "The TODO service rejected the create request.",
                });
                return (false, null);
            }

            return (true, result.Item?.Id ?? draft.Id);
        }
        catch (OperationCanceledException)
        {
            using var cancelCts = CreateCompensationCts();
            var afterCancel = await todoService.GetByIdAsync(draft.Id!, cancelCts.Token).ConfigureAwait(false);
            if (afterCancel is not null && IsHeal(afterCancel, intentId, draft))
            {
                entity.CreatedTodoId = afterCancel.Id;
                entity.ReviewState = nameof(HandoffReviewState.Created);
                entity.ProcessingState = nameof(HandoffProcessingState.Terminal);
                entity.Succeeded = true;
                entity.Error = null;
                entity.ErrorCode = null;
                if (!await TryCompensateCreatedRunAsync(entity).ConfigureAwait(false))
                    throw new InvalidOperationException(HandoffErrorCodes.CompensationFailed);
            }

            throw;
        }
    }

private async Task<HandoffIngestionResult> PersistAsync(
        HandoffIngestionRequest request,
        string workspacePath,
        HandoffResolvedSource resolved,
        HandoffTodoDraft? draft,
        List<HandoffDiagnostic> diagnostics,
        bool created,
        bool replayed,
        bool requiresReview,
        HandoffReviewState reviewState,
        string? createdTodoId,
        string? agent,
        string? model,
        bool success,
        string? error,
        CancellationToken cancellationToken,
        string? errorCode = null)
    {
        var runId = $"handoff-run-{Guid.NewGuid():N}";
        var sanitizedDraft = SanitizeDraft(draft);
        var entity = new HandoffIngestionRunEntity
        {
            RunId = runId,
            WorkspaceId = workspacePath,
            SourceKind = resolved.SourceKind.ToString(),
            SourceLocator = SanitizeText(resolved.Locator) ?? resolved.Locator,
            ContentSha256 = resolved.ContentSha256 ?? string.Empty,
            ExtractedAtUtc = _time.GetUtcNow(),
            PromptVersion = HandoffPromptDefaults.PromptVersion,
            TemplateVersion = HandoffPromptDefaults.TemplateId,
            Agent = SanitizeText(agent),
            Model = SanitizeText(model),
            Confidence = sanitizedDraft?.Confidence,
            Mode = request.Mode.ToString(),
            ReviewState = reviewState.ToString(),
            CreatedTodoId = createdTodoId,
            DraftJson = sanitizedDraft is null ? null : JsonSerializer.Serialize(sanitizedDraft, DraftJsonOptions),
            Force = request.Force,
            ReplayIdentity = HandoffReplayKeys.Create(
                workspacePath,
                resolved.ContentSha256 ?? string.Empty,
                HandoffPromptDefaults.PromptVersion,
                request.Force || string.IsNullOrEmpty(resolved.ContentSha256),
                runId),
            ProcessingState = nameof(HandoffProcessingState.Terminal),
            Succeeded = success,
            Error = SanitizeText(error),
            ErrorCode = errorCode,
        };
        ReplaceDiagnostics(entity, diagnostics);
        _db.HandoffIngestionRuns.Add(entity);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        var result = MapEntity(entity, replayed);
        result.Success = success;
        result.Created = created;
        result.RequiresReview = requiresReview;
        result.Error = error;
        result.ErrorCode = errorCode;
        return result;
    }

private async Task<(HandoffIngestionRunEntity? Entity, bool Replayed, bool InProgress)> TryReserveRunAsync(
        HandoffIngestionRequest request,
        string workspacePath,
        HandoffResolvedSource resolved,
        CancellationToken cancellationToken)
    {
        var runId = $"handoff-run-{Guid.NewGuid():N}";
        var identity = HandoffReplayKeys.Create(
            workspacePath,
            resolved.ContentSha256 ?? string.Empty,
            HandoffPromptDefaults.PromptVersion,
            request.Force,
            runId);
        if (!request.Force)
        {
            var existing = await _db.HandoffIngestionRuns
                .Include(run => run.Diagnostics)
                .FirstOrDefaultAsync(run => run.ReplayIdentity == identity, cancellationToken)
                .ConfigureAwait(false);
            if (existing is not null)
                return await ResolveExistingReservationAsync(existing, cancellationToken).ConfigureAwait(false);
        }

        var now = _time.GetUtcNow();
        var entity = new HandoffIngestionRunEntity
        {
            RunId = runId,
            WorkspaceId = workspacePath,
            SourceKind = resolved.SourceKind.ToString(),
            SourceLocator = SanitizeText(resolved.Locator) ?? resolved.Locator,
            ContentSha256 = resolved.ContentSha256 ?? string.Empty,
            ExtractedAtUtc = now,
            PromptVersion = HandoffPromptDefaults.PromptVersion,
            TemplateVersion = HandoffPromptDefaults.TemplateId,
            Mode = request.Mode.ToString(),
            ReviewState = nameof(HandoffReviewState.None),
            Force = request.Force,
            ReplayIdentity = identity,
            Succeeded = false,
            ProcessingState = nameof(HandoffProcessingState.Processing),
            ProcessingOwner = _instanceId,
            ProcessingLeaseExpiresAtUtc = now.Add(_lease.Duration),
        };
        _db.HandoffIngestionRuns.Add(entity);
        try
        {
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return (entity, false, false);
        }
        catch (DbUpdateException ex) when (HandoffDbExceptions.IsUniqueViolation(ex))
        {
            _db.Entry(entity).State = EntityState.Detached;
            var winner = await _db.HandoffIngestionRuns
                .Include(run => run.Diagnostics)
                .FirstAsync(run => run.ReplayIdentity == identity, cancellationToken)
                .ConfigureAwait(false);
            return await ResolveExistingReservationAsync(winner, cancellationToken).ConfigureAwait(false);
        }
    }

private async Task<(HandoffIngestionRunEntity Entity, bool Replayed, bool InProgress)> ResolveExistingReservationAsync(
        HandoffIngestionRunEntity existing,
        CancellationToken cancellationToken)
    {
        var now = _time.GetUtcNow();
        var isTerminal = existing.ProcessingState == nameof(HandoffProcessingState.Terminal)
            || existing.ReviewState is nameof(HandoffReviewState.Created)
                or nameof(HandoffReviewState.Failed)
                or nameof(HandoffReviewState.Rejected)
                or nameof(HandoffReviewState.PendingReview);
        if (isTerminal && existing.ProcessingState != nameof(HandoffProcessingState.Processing))
            return (existing, true, false);

        var leaseLive = existing.ProcessingState == nameof(HandoffProcessingState.Processing)
            && existing.ProcessingLeaseExpiresAtUtc is { } expires
            && expires >= now
            && !string.Equals(existing.ProcessingOwner, _instanceId, StringComparison.Ordinal);
        if (leaseLive)
            return (existing, false, true);

        var taken = await _db.HandoffIngestionRuns
            .Where(run => run.RunId == existing.RunId
                && run.ProcessingState == nameof(HandoffProcessingState.Processing)
                && run.StateVersion == existing.StateVersion
                && (run.ProcessingLeaseExpiresAtUtc == null || run.ProcessingLeaseExpiresAtUtc < now))
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.ProcessingOwner, _instanceId)
                    .SetProperty(run => run.ProcessingLeaseExpiresAtUtc, now.Add(_lease.Duration))
                    .SetProperty(run => run.StateVersion, run => run.StateVersion + 1),
                cancellationToken)
            .ConfigureAwait(false);
        if (taken == 0)
        {
            var current = await _db.HandoffIngestionRuns
                .AsNoTracking()
                .Include(run => run.Diagnostics)
                .FirstAsync(run => run.RunId == existing.RunId, cancellationToken)
                .ConfigureAwait(false);
            if (current.ProcessingState == nameof(HandoffProcessingState.Terminal))
                return (current, true, false);
            return (current, false, true);
        }

        _db.Entry(existing).State = EntityState.Detached;
        var owned = await _db.HandoffIngestionRuns
            .Include(run => run.Diagnostics)
            .FirstAsync(run => run.RunId == existing.RunId, cancellationToken)
            .ConfigureAwait(false);
        return (owned, false, false);
    }

private async Task<HandoffIngestionResult> CompleteReservedRunAsync(
        HandoffIngestionRunEntity entity,
        HandoffIngestionRequest request,
        HandoffTodoDraft? draft,
        List<HandoffDiagnostic> diagnostics,
        bool created,
        bool requiresReview,
        HandoffReviewState reviewState,
        string? createdTodoId,
        string? agent,
        string? model,
        bool success,
        string? error,
        string? errorCode,
        string? promptVersion,
        string? templateVersion,
        CancellationToken cancellationToken)
    {
        var sanitizedDraft = SanitizeDraft(draft);
        var claimedVersion = entity.StateVersion;
        var effectivePrompt = string.IsNullOrWhiteSpace(promptVersion)
            ? HandoffPromptDefaults.PromptVersion
            : promptVersion.Trim();
        var effectiveTemplate = string.IsNullOrWhiteSpace(templateVersion)
            ? HandoffPromptDefaults.TemplateId
            : templateVersion.Trim();
        var fenced = await _db.HandoffIngestionRuns
            .Where(run => run.RunId == entity.RunId
                && run.ProcessingOwner == _instanceId
                && run.StateVersion == claimedVersion)
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.PromptVersion, effectivePrompt)
                    .SetProperty(run => run.TemplateVersion, effectiveTemplate)
                    .SetProperty(run => run.Agent, SanitizeText(agent))
                    .SetProperty(run => run.Model, SanitizeText(model))
                    .SetProperty(run => run.Confidence, sanitizedDraft?.Confidence)
                    .SetProperty(run => run.Mode, request.Mode.ToString())
                    .SetProperty(run => run.ReviewState, reviewState.ToString())
                    .SetProperty(run => run.ProcessingState, nameof(HandoffProcessingState.Terminal))
                    .SetProperty(run => run.ProcessingOwner, (string?)null)
                    .SetProperty(run => run.ProcessingLeaseExpiresAtUtc, (DateTimeOffset?)null)
                    .SetProperty(run => run.CreatedTodoId, createdTodoId)
                    .SetProperty(run => run.DraftJson, sanitizedDraft is null ? null : JsonSerializer.Serialize(sanitizedDraft, DraftJsonOptions))
                    .SetProperty(run => run.Succeeded, success)
                    .SetProperty(run => run.Error, SanitizeText(error))
                    .SetProperty(run => run.ErrorCode, errorCode)
                    .SetProperty(run => run.StateVersion, claimedVersion + 1),
                cancellationToken)
            .ConfigureAwait(false);
        if (fenced == 0)
            return InProgressResult(entity);

        entity.PromptVersion = effectivePrompt;
        entity.TemplateVersion = effectiveTemplate;
        entity.Agent = SanitizeText(agent);
        entity.Model = SanitizeText(model);
        entity.Confidence = sanitizedDraft?.Confidence;
        entity.Mode = request.Mode.ToString();
        entity.ReviewState = reviewState.ToString();
        entity.ProcessingState = nameof(HandoffProcessingState.Terminal);
        entity.ProcessingOwner = null;
        entity.ProcessingLeaseExpiresAtUtc = null;
        entity.CreatedTodoId = createdTodoId;
        entity.DraftJson = sanitizedDraft is null ? null : JsonSerializer.Serialize(sanitizedDraft, DraftJsonOptions);
        entity.Succeeded = success;
        entity.Error = SanitizeText(error);
        entity.ErrorCode = errorCode;
        entity.StateVersion = claimedVersion + 1;
        ReplaceDiagnostics(entity, diagnostics);
        try
        {
            if (!await SaveRunAfterTodoAsync(entity, cancellationToken).ConfigureAwait(false))
                return created ? CompensationFailedResult(entity) : FailedPersistResult(entity, error, errorCode);
        }
        catch (OperationCanceledException) when (created && !cancellationToken.IsCancellationRequested)
        {
            return CompensationFailedResult(entity);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception) when (created)
        {
            return CompensationFailedResult(entity);
        }

        var result = MapEntity(entity, replayed: false);
        result.Success = success;
        result.Created = created;
        result.RequiresReview = requiresReview;
        result.Error = error;
        result.ErrorCode = errorCode;
        return result;
    }

private async Task<bool> SaveRunAfterTodoAsync(HandoffIngestionRunEntity entity, CancellationToken cancellationToken)
    {
        try
        {
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            return true;
        }
        catch (OperationCanceledException) when (!string.IsNullOrWhiteSpace(entity.CreatedTodoId))
        {
            if (!await TryCompensateCreatedRunAsync(entity).ConfigureAwait(false))
                throw;
            throw;
        }
        catch (Exception ex) when (!string.IsNullOrWhiteSpace(entity.CreatedTodoId) && HandoffDbExceptions.IsCommitAmbiguous(ex))
        {
            if (!await TryCompensateCreatedRunAsync(entity).ConfigureAwait(false))
                throw;
            return true;
        }
    }

private async Task<bool> TryCompensateCreatedRunAsync(HandoffIngestionRunEntity entity)
    {
        using var cts = new CancellationTokenSource(_lease.CompensationTimeout);
        var token = cts.Token;
        var todo = await _workspaceAccessor.GetTodoService()
            .GetByIdAsync(entity.CreatedTodoId!, token)
            .ConfigureAwait(false);
        if (todo is null)
            return false;

        await using var fresh = CreateFreshContext();
        fresh.OverrideWorkspaceId(entity.WorkspaceId);
        var updated = await fresh.HandoffIngestionRuns
            .Where(run => run.RunId == entity.RunId
                && (run.ProcessingOwner == _instanceId || run.ApprovalOwner == _instanceId || run.CreatedTodoId == entity.CreatedTodoId))
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.ReviewState, nameof(HandoffReviewState.Created))
                    .SetProperty(run => run.ProcessingState, nameof(HandoffProcessingState.Terminal))
                    .SetProperty(run => run.ProcessingOwner, (string?)null)
                    .SetProperty(run => run.ProcessingLeaseExpiresAtUtc, (DateTimeOffset?)null)
                    .SetProperty(run => run.CreatedTodoId, entity.CreatedTodoId)
                    .SetProperty(run => run.TodoCreationIntentId, entity.TodoCreationIntentId)
                    .SetProperty(run => run.Succeeded, true)
                    .SetProperty(run => run.Error, (string?)null)
                    .SetProperty(run => run.ErrorCode, (string?)null)
                    .SetProperty(run => run.DraftJson, entity.DraftJson)
                    .SetProperty(run => run.Agent, entity.Agent)
                    .SetProperty(run => run.Model, entity.Model)
                    .SetProperty(run => run.Confidence, entity.Confidence),
                token)
            .ConfigureAwait(false);
        if (updated == 0)
            return false;

        entity.ReviewState = nameof(HandoffReviewState.Created);
        entity.ProcessingState = nameof(HandoffProcessingState.Terminal);
        entity.Succeeded = true;
        return true;
    }

private async Task<HandoffIngestionResult> TerminalizeReservedRunAsync(
        HandoffIngestionRunEntity entity,
        string errorCode,
        string error,
        CancellationToken cancellationToken)
    {
        _ = cancellationToken;
        using var cts = CreateCompensationCts();
        var token = cts.Token;
        if (!await OwnsProcessingAsync(entity, token).ConfigureAwait(false))
            return InProgressResult(entity);

        var version = entity.StateVersion;
        var fenced = await _db.HandoffIngestionRuns
            .Where(run => run.RunId == entity.RunId
                && run.ProcessingOwner == _instanceId
                && run.StateVersion == version)
            .ExecuteUpdateAsync(
                setters => setters
                    .SetProperty(run => run.ReviewState, nameof(HandoffReviewState.Failed))
                    .SetProperty(run => run.ProcessingState, nameof(HandoffProcessingState.Terminal))
                    .SetProperty(run => run.ProcessingOwner, (string?)null)
                    .SetProperty(run => run.ProcessingLeaseExpiresAtUtc, (DateTimeOffset?)null)
                    .SetProperty(run => run.Succeeded, false)
                    .SetProperty(run => run.Error, SanitizeText(error))
                    .SetProperty(run => run.ErrorCode, errorCode)
                    .SetProperty(run => run.StateVersion, version + 1),
                token)
            .ConfigureAwait(false);
        if (fenced == 0)
            return InProgressResult(entity);

        entity.ReviewState = nameof(HandoffReviewState.Failed);
        entity.ProcessingState = nameof(HandoffProcessingState.Terminal);
        entity.ProcessingOwner = null;
        entity.ProcessingLeaseExpiresAtUtc = null;
        entity.Succeeded = false;
        entity.Error = SanitizeText(error);
        entity.ErrorCode = errorCode;
        entity.StateVersion = version + 1;
        var result = MapEntity(entity, replayed: false);
        result.Success = false;
        result.Error = entity.Error;
        result.ErrorCode = errorCode;
        return result;
    }

private async Task RenewProcessingLeaseLoopAsync(HandoffIngestionRunEntity entity, CancellationToken cancellationToken)
    {
        try
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                await WaitForHeartbeatIntervalAsync(cancellationToken).ConfigureAwait(false);
                var now = _time.GetUtcNow();
                await using var db = CreateFreshContext();
                var renewed = await db.HandoffIngestionRuns
                    .Where(run => run.RunId == entity.RunId
                        && run.ProcessingOwner == _instanceId
                        && run.ProcessingState == nameof(HandoffProcessingState.Processing)
                        && run.StateVersion == entity.StateVersion)
                    .ExecuteUpdateAsync(
                        setters => setters
                            .SetProperty(run => run.ProcessingLeaseExpiresAtUtc, now.Add(_lease.Duration)),
                        cancellationToken)
                    .ConfigureAwait(false);
                if (renewed == 0)
                    return;
                entity.ProcessingLeaseExpiresAtUtc = now.Add(_lease.Duration);
            }
        }
        catch (OperationCanceledException)
        {
        }
    }

public async Task<HostileReviewResult> AcceptReviewerOutputAsync(string requestId, HostileReviewerOutput output, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(output);
        var entity = await LoadAsync(requestId, cancellationToken).ConfigureAwait(false);
        if (entity is null)
            return NotFound(requestId);

        if (!string.Equals(output.Model, HostileReviewPromptDefaults.RequiredModel, StringComparison.Ordinal)
            || !string.Equals(output.Effort, HostileReviewPromptDefaults.RequiredEffort, StringComparison.Ordinal))
        {
            entity.Status = "Failed";
            entity.LastErrorCode = "ModelUnavailable";
            entity.UpdatedUtc = _time.GetUtcNow();
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            var failed = Map(entity);
            failed.ErrorCode = "ModelUnavailable";
            failed.Success = false;
            return failed;
        }

        if (!AllowedVerdicts.Contains(output.Verdict))
        {
            entity.Status = "Failed";
            entity.LastErrorCode = "malformed_output";
            entity.UpdatedUtc = _time.GetUtcNow();
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            var failed = Map(entity);
            failed.ErrorCode = "malformed_output";
            failed.Success = false;
            return failed;
        }

        var now = _time.GetUtcNow();
        entity.Executions.Add(new HostileReviewExecutionEntity
        {
            ExecutionId = $"hrex-{Guid.NewGuid():N}",
            RequestId = entity.RequestId,
            WorkspaceId = entity.WorkspaceId,
            ReviewerAgent = output.ReviewerAgent,
            Model = output.Model,
            Effort = output.Effort,
            SourceSurface = output.SourceSurface,
            PromptTemplateId = output.PromptTemplateId,
            PromptVersion = output.PromptVersion,
            StartedUtc = now,
            EndedUtc = now,
            InputTokens = output.InputTokens,
            OutputTokens = output.OutputTokens,
        });

        foreach (var finding in output.Findings)
        {
            var category = AllowedCategories.Contains(finding.Category) ? finding.Category : "uncertainty";
            entity.Findings.Add(new HostileReviewFindingEntity
            {
                RequestId = entity.RequestId,
                WorkspaceId = entity.WorkspaceId,
                Category = category,
                Severity = string.IsNullOrWhiteSpace(finding.Severity) ? "medium" : finding.Severity,
                ArtifactId = finding.ArtifactId,
                Location = finding.Location,
                RequirementId = finding.RequirementId,
                EvidenceSummary = finding.EvidenceSummary,
                Recommendation = finding.Recommendation,
            });
        }

        entity.Verdict = output.Verdict.ToUpperInvariant();
        entity.QualityDisclosure = output.RequestQuality.Disclosure;
        entity.QualityScopeClarity = output.RequestQuality.ScopeClarity;
        entity.QualityObjectiveClarity = output.RequestQuality.ObjectiveClarity;
        entity.QualityConfidence = output.RequestQuality.Confidence;
        entity.QualityEnoughContext = output.RequestQuality.EnoughContext;
        entity.Status = "Succeeded";
        entity.UpdatedUtc = now;
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return Map(entity);
    }

public async Task<HostileReviewResult> SubmitAsync(HostileReviewSubmitRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        cancellationToken.ThrowIfCancellationRequested();

        if (!string.IsNullOrWhiteSpace(request.WorkspacePath)
            && !IsSameWorkspace(request.WorkspacePath, _workspaceId, QBrainAi.Client.WorkspacePathNormalizer.Process)
            && !string.Equals(request.WorkspacePath, _workspaceId, StringComparison.OrdinalIgnoreCase))
        {
            return new HostileReviewResult
            {
                Success = false,
                HttpStatus = 403,
                ErrorCode = "foreign_workspace",
                Error = "The request workspace does not match the authenticated workspace.",
            };
        }

        var payload = request.SerializedPayload ?? JsonSerializer.Serialize(request);
        var payloadBytes = Encoding.UTF8.GetByteCount(payload);
        if (payloadBytes > _options.MaximumSubmitBytes)
        {
            return new HostileReviewResult
            {
                Success = false,
                HttpStatus = 400,
                ErrorCode = "payload_too_large",
                Error = "Serialized request exceeds 1,048,576 bytes.",
            };
        }

        if (request.Links.Count > _options.MaximumLinks)
        {
            return new HostileReviewResult
            {
                Success = false,
                HttpStatus = 400,
                ErrorCode = "too_many_links",
                Error = "More than 64 artifact links is rejected.",
            };
        }

        var active = await _db.HostileReviewRequests
            .CountAsync(item => item.Status == "Queued" || item.Status == "Claimed" || item.Status == "Running", cancellationToken)
            .ConfigureAwait(false);
        if (active >= _options.MaximumActiveQueue)
        {
            return new HostileReviewResult
            {
                Success = false,
                HttpStatus = 429,
                ErrorCode = "queue_full",
                Error = "Hostile review queue is at capacity.",
            };
        }

        var now = _time.GetUtcNow();
        var requestId = $"hr-{now:yyyyMMddHHmmss}-{Guid.NewGuid():N}";
        var entity = new HostileReviewRequestEntity
        {
            RequestId = requestId,
            WorkspaceId = _workspaceId,
            TargetType = string.IsNullOrWhiteSpace(request.TargetType) ? "code" : request.TargetType.Trim(),
            Mode = string.IsNullOrWhiteSpace(request.Mode) ? "adversarial" : request.Mode.Trim(),
            ScopeStatement = request.ScopeStatement ?? string.Empty,
            RequestingAgent = string.IsNullOrWhiteSpace(request.RequestingAgent) ? "unknown" : request.RequestingAgent.Trim(),
            Status = "Queued",
            CreatedUtc = now,
            UpdatedUtc = now,
        };

        foreach (var link in request.Links)
        {
            var resolution = ResolveLink(link);
            entity.Links.Add(new HostileReviewArtifactLinkEntity
            {
                RequestId = requestId,
                WorkspaceId = _workspaceId,
                ArtifactType = string.IsNullOrWhiteSpace(link.ArtifactType) ? "unknown" : link.ArtifactType.Trim(),
                ArtifactId = link.ArtifactId ?? string.Empty,
                ContentSha256 = resolution.Hash,
                Resolved = resolution.Resolved,
            });
            if (!string.IsNullOrWhiteSpace(resolution.DiagnosticCode))
            {
                entity.Diagnostics.Add(new HostileReviewDiagnosticEntity
                {
                    RequestId = requestId,
                    WorkspaceId = _workspaceId,
                    Code = resolution.DiagnosticCode,
                    Message = resolution.DiagnosticMessage ?? resolution.DiagnosticCode,
                });
            }
        }

        _db.HostileReviewRequests.Add(entity);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return Map(entity);
    }

internal async Task<MigrationOutcome> RunAsync(CancellationToken cancellationToken)
    {
        var opts = _storageOptions.Value;
        if (!opts.MigrateFromLegacySqlite)
        {
            _logger.LogInformation("LegacyTodoSqliteMigrator: disabled via Mcp:TodoStorage:MigrateFromLegacySqlite=false; no-op.");
            return MigrationOutcome.SkippedByFlag;
        }

        var legacyPath = ResolveLegacyPath(opts);
        if (string.IsNullOrWhiteSpace(legacyPath) || !File.Exists(legacyPath))
        {
            _logger.LogInformation("LegacyTodoSqliteMigrator: no legacy SQLite file at '{Path}'; no-op.", legacyPath);
            return MigrationOutcome.SkippedMissingFile;
        }

        var markerPath = legacyPath + MarkerFileSuffix;
        if (File.Exists(markerPath))
        {
            _logger.LogInformation("LegacyTodoSqliteMigrator: marker '{Marker}' present; no-op.", markerPath);
            return MigrationOutcome.SkippedMarkerPresent;
        }

        await using var scope = _scopeFactory.CreateAsyncScope();
        var ctx = scope.ServiceProvider.GetRequiredService<McpDbContext>();

        if (await ctx.TodoItems.AnyAsync(cancellationToken).ConfigureAwait(false))
        {
            await WriteMarkerAsync(markerPath, "target non-empty", cancellationToken).ConfigureAwait(false);
            _logger.LogInformation("LegacyTodoSqliteMigrator: target already has TODO rows; wrote marker and exited.");
            return MigrationOutcome.SkippedTargetPopulated;
        }

        var (items, history, metadata) = await ReadLegacyAsync(legacyPath, cancellationToken).ConfigureAwait(false);

        foreach (var item in items)
        {
            ctx.TodoItems.Add(item);
            ctx.TodoItemListItems.AddRange(item.ListItems);
            ctx.TodoItemTasks.AddRange(item.ImplementationTaskRows);
        }

        foreach (var row in history)
            ctx.TodoAuditHistory.Add(row);
        if (metadata is not null)
        {
            ctx.TodoDocumentMetadata.Add(metadata);
            ctx.TodoDocumentNotes.AddRange(metadata.Notes);
            ctx.TodoCompletedGroups.AddRange(metadata.CompletedGroups);
        }

        await ctx.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await WriteMarkerAsync(markerPath, $"imported items={items.Count} history={history.Count} meta={(metadata is null ? 0 : 1)}", cancellationToken).ConfigureAwait(false);
        _logger.LogInformation(
            "LegacyTodoSqliteMigrator: imported {Items} TODO items, {History} audit rows, {Meta} metadata row(s) from '{Path}'.",
            items.Count, history.Count, metadata is null ? 0 : 1, legacyPath);
        return MigrationOutcome.Migrated;
    }

public async Task<MemoryMutationResult> UpdateAsync(string id, MemoryUpdateRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);

        var normalizedId = NormalizeId(id);
        if (!IsValidMemoryId(normalizedId))
            return Validation("Memory id must match MEMORY-{CATEGORY}-{NNN}.");

        var entity = await _db.Memories
            .FirstOrDefaultAsync(memory => memory.Id == normalizedId, cancellationToken)
            .ConfigureAwait(false);
        if (entity is null)
            return new MemoryMutationResult(false, $"Memory '{normalizedId}' not found.", FailureKind: MemoryMutationFailureKind.NotFound);

        if (request.Category is not null)
        {
            var category = NormalizeCategory(request.Category);
            if (category is null)
                return Validation("Memory category cannot be empty.");
            entity.Category = category;
        }

        if (request.Scope is not null)
        {
            if (!Enum.IsDefined(request.Scope.Value))
                return Validation("Memory scope must be Global or Workspace.");

            var workspaceId = ResolveWorkspaceId(request.Scope.Value);
            if (request.Scope.Value == MemoryScope.Workspace && workspaceId is null)
                return Validation("Workspace memory requires an active workspace.");

            entity.Scope = ToEntityScope(request.Scope.Value);
            entity.WorkspaceId = workspaceId;
        }

        var contentChanged = false;
        if (request.Text is not null)
        {
            if (string.IsNullOrWhiteSpace(request.Text))
                return Validation("Memory text cannot be empty.");
            if (MemoryPolicy.RejectsSecrets(request.Text))
                return Validation("Memory content matches a rejected secret pattern.");
            entity.Text = request.Text;
            entity.Content = request.Text;
            contentChanged = true;
        }

        if (request.Content is not null)
        {
            if (string.IsNullOrWhiteSpace(request.Content))
                return Validation("Memory content cannot be empty.");
            if (MemoryPolicy.RejectsSecrets(request.Content))
                return Validation("Memory content matches a rejected secret pattern.");
            entity.Content = request.Content;
            entity.Text = request.Content;
            contentChanged = true;
        }

        if (request.Title is not null)
        {
            if (request.Title.Length > MemoryLimits.MaxTitleLength)
                return Validation("Title exceeds the configured maximum length.");
            entity.Title = NormalizeOptional(request.Title);
        }

        if (request.Summary is not null)
            entity.Summary = NormalizeOptional(request.Summary);

        if (request.Type is not null)
        {
            if (!MemoryLimits.AllowedTypes.Contains(request.Type.Trim()))
                return Validation("Type is not an allowed memory type.");
            entity.Type = NormalizeOptional(request.Type);
        }

        if (request.Tags is not null)
        {
            if (request.Tags.Any(tag => tag is { Length: > MemoryLimits.MaxTagLength }))
                return Validation("Tag exceeds the configured maximum length.");
            entity.Tags = MemoryLayerMapper.SerializeTags(request.Tags);
        }

        if (request.Confidence is not null)
        {
            if (request.Confidence is < 0 or > 1)
                return Validation("Confidence must be in [0,1].");
            entity.Confidence = request.Confidence;
        }

        if (request.SourceKind is not null)
            entity.SourceKind = NormalizeOptional(request.SourceKind);
        if (request.SourceRef is not null)
            entity.SourceRef = NormalizeOptional(request.SourceRef);

        entity.Version++;
        entity.UpdatedAtUtc = _timeProvider.GetUtcNow();
        if (request.UpdatedBy is not null)
            entity.UpdatedBy = NormalizeOptional(request.UpdatedBy);
        if (contentChanged)
            entity.EmbeddingStatus = "pending";

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        if (contentChanged)
            await new MemoryCompetitiveOperations(_db).AppendVersionAsync(entity, cancellationToken).ConfigureAwait(false);
        await MemorySessionLogHook.TryAppendAsync(_db, entity.Id, "memory_update", cancellationToken).ConfigureAwait(false);
        _logger.LogInformation("Memory updated: {MemoryId}", entity.Id);
        return new MemoryMutationResult(true, Memory: MemoryLayerMapper.ToItem(entity));
    }

public async Task<MemoryMutationResult> RemoveAsync(string id, CancellationToken cancellationToken = default)
    {
        var normalizedId = NormalizeId(id);
        if (!IsValidMemoryId(normalizedId))
            return Validation("Memory id must match MEMORY-{CATEGORY}-{NNN}.");

        var entity = await _db.Memories
            .FirstOrDefaultAsync(memory => memory.Id == normalizedId, cancellationToken)
            .ConfigureAwait(false);
        if (entity is null)
            return new MemoryMutationResult(false, $"Memory '{normalizedId}' not found.", FailureKind: MemoryMutationFailureKind.NotFound);

        var item = MemoryLayerMapper.ToItem(entity);
        var entry = _db.Entry(entity);
        entry.Property<bool>("IsDeleted").CurrentValue = true;
        entry.Property<DateTimeOffset?>("DeletedAtUtc").CurrentValue = _timeProvider.GetUtcNow();
        entry.Property<string?>("DeletedBy").CurrentValue = "MemoryService";
        entry.Property<string?>("DeleteReason").CurrentValue = "memory_remove";
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await MemorySessionLogHook.TryAppendAsync(_db, entity.Id, "memory_remove", cancellationToken).ConfigureAwait(false);
        _logger.LogInformation("Memory removed: {MemoryId}", entity.Id);
        return new MemoryMutationResult(true, Memory: item);
    }

public async Task<MemoryMutationResult> AddAsync(MemoryAddRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);

        var category = NormalizeCategory(request.Category);
        if (category is null)
            return Validation("Memory category is required.");

        if (string.IsNullOrWhiteSpace(request.Text) && string.IsNullOrWhiteSpace(request.Content))
            return Validation("Memory text is required.");

        if (!Enum.IsDefined(request.Scope))
            return Validation("Memory scope must be Global or Workspace.");

        var content = string.IsNullOrWhiteSpace(request.Content) ? request.Text : request.Content;
        if (MemoryPolicy.RejectsSecrets(content) || MemoryPolicy.RejectsSecrets(request.Text))
            return Validation("Memory content matches a rejected secret pattern.");

        if (request.Title is { Length: > MemoryLimits.MaxTitleLength })
            return Validation("Title exceeds the configured maximum length.");
        if (content.Length > MemoryLimits.MaxContentLength)
            return Validation("Content exceeds the configured maximum length.");
        if (request.Tags is not null && request.Tags.Any(tag => tag is { Length: > MemoryLimits.MaxTagLength }))
            return Validation("Tag exceeds the configured maximum length.");
        if (request.Confidence is < 0 or > 1)
            return Validation("Confidence must be in [0,1].");
        if (!string.IsNullOrWhiteSpace(request.Type)
            && !MemoryLimits.AllowedTypes.Contains(request.Type.Trim()))
        {
            return Validation("Type is not an allowed memory type.");
        }

        var workspaceId = ResolveWorkspaceId(request.Scope);
        if (request.Scope == MemoryScope.Workspace && workspaceId is null)
            return Validation("Workspace memory requires an active workspace.");

        var id = string.IsNullOrWhiteSpace(request.Id)
            ? await GenerateNextIdAsync(category, cancellationToken).ConfigureAwait(false)
            : NormalizeId(request.Id);
        if (!IsValidMemoryId(id))
            return Validation("Memory id must match MEMORY-{CATEGORY}-{NNN}.");

        var duplicate = await _db.Memories
            .IgnoreQueryFilters()
            .AnyAsync(memory => memory.Id == id, cancellationToken)
            .ConfigureAwait(false);
        if (duplicate)
            return new MemoryMutationResult(false, $"Memory '{id}' already exists.", FailureKind: MemoryMutationFailureKind.Conflict);

        var now = _timeProvider.GetUtcNow();
        var entity = new MemoryEntity
        {
            Id = id,
            Category = category,
            Scope = ToEntityScope(request.Scope),
            WorkspaceId = workspaceId,
            Text = string.IsNullOrWhiteSpace(request.Text) ? content : request.Text,
            Version = 1,
            CreatedAtUtc = now,
            UpdatedAtUtc = now,
            UpdatedBy = NormalizeOptional(request.UpdatedBy),
            Title = NormalizeOptional(request.Title),
            Summary = NormalizeOptional(request.Summary),
            Content = content,
            Type = NormalizeOptional(request.Type),
            Tags = MemoryLayerMapper.SerializeTags(request.Tags),
            Confidence = request.Confidence ?? MemoryLimits.DefaultConfidence,
            SourceKind = NormalizeOptional(request.SourceKind),
            SourceRef = NormalizeOptional(request.SourceRef),
            CreatedBy = NormalizeOptional(request.CreatedBy),
            EmbeddingStatus = "pending",
        };

        _db.Memories.Add(entity);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await new MemoryCompetitiveOperations(_db).AppendVersionAsync(entity, cancellationToken).ConfigureAwait(false);
        await MemorySessionLogHook.TryAppendAsync(_db, entity.Id, "memory_add", cancellationToken).ConfigureAwait(false);
        _logger.LogInformation("Memory created: {MemoryId} ({Scope})", entity.Id, entity.Scope);
        return new MemoryMutationResult(true, Memory: MemoryLayerMapper.ToItem(entity));
    }

public async Task<bool> DeleteTurnItemAsync(string sourceType, string sessionId, string requestId, string section, string itemKey, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(requestId);
        ArgumentNullException.ThrowIfNull(itemKey);
        SyncDbWorkspaceFromContext();

        var parsed = ParseSection(section);
        ValidateTurnIdentifiers(sourceType, sessionId, requestId);

        var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false);
        var turnEntity = session?.Turns.FirstOrDefault(t => t.RequestId == requestId);
        if (session is null || turnEntity is null)
            return false;

        if (!RemoveSectionItem(turnEntity, parsed, itemKey))
            return false;

        StampTurnChildren(turnEntity, session.WorkspaceId);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return true;
    }

public async Task<bool> DeleteTurnAsync(string sourceType, string sessionId, string requestId, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(requestId);
        SyncDbWorkspaceFromContext();
        ValidateTurnIdentifiers(sourceType, sessionId, requestId);

        await using var _ = await s_deleteTurnLock.AcquireAsync($"{sourceType}/{sessionId}", cancellationToken).ConfigureAwait(false);

        var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false);
        var turnEntity = session?.Turns.FirstOrDefault(t => t.RequestId == requestId);
        if (session is null || turnEntity is null)
            return false;

        var sessionRowId = session.Id;
        var turnId = turnEntity.Id;

        // Child FKs are DeleteBehavior.Restrict (no cascade); soft-delete bottom-up with
        // bulk ExecuteUpdate so durable session-log rows retain deletion metadata.
        // Drop tracked entities first so they cannot conflict with bulk updates.
        _db.ChangeTracker.Clear();
        await SoftDeleteTurnRowsAsync(
            turnId,
            DateTimeOffset.UtcNow,
            "session_log_turn_delete",
            cancellationToken).ConfigureAwait(false);

        var remaining = await _db.SessionLogTurns
            .CountAsync(t => t.SessionLogId == sessionRowId, cancellationToken).ConfigureAwait(false);
        await _db.SessionLogs
            .Where(s => s.Id == sessionRowId)
            .ExecuteUpdateAsync(setters => setters.SetProperty(s => s.TurnCount, remaining), cancellationToken)
            .ConfigureAwait(false);

        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return true;
    }

private static Task<int> SoftDeleteRowsAsync<TEntity>(
        IQueryable<TEntity> query,
        DateTimeOffset deletedAtUtc,
        string reason,
        CancellationToken cancellationToken)
        where TEntity : class
    {
        return query.ExecuteUpdateAsync(
            setters => setters
                .SetProperty(entity => EF.Property<bool>(entity, "IsDeleted"), true)
                .SetProperty(entity => EF.Property<DateTimeOffset?>(entity, "DeletedAtUtc"), deletedAtUtc)
                .SetProperty(entity => EF.Property<string?>(entity, "DeletedBy"), nameof(SessionLogService))
                .SetProperty(entity => EF.Property<string?>(entity, "DeleteReason"), reason),
            cancellationToken);
    }

private static Task<int> RestoreRowsAsync<TEntity>(
        IQueryable<TEntity> query,
        CancellationToken cancellationToken)
        where TEntity : class
    {
        return query.ExecuteUpdateAsync(
            setters => setters
                .SetProperty(entity => EF.Property<bool>(entity, "IsDeleted"), false)
                .SetProperty(entity => EF.Property<DateTimeOffset?>(entity, "DeletedAtUtc"), (DateTimeOffset?)null)
                .SetProperty(entity => EF.Property<string?>(entity, "DeletedBy"), (string?)null)
                .SetProperty(entity => EF.Property<string?>(entity, "DeleteReason"), (string?)null),
            cancellationToken);
    }

public async Task<int> AppendProcessingDialogAsync(
        string sourceType,
        string sessionId,
        string requestId,
        IReadOnlyList<ProcessingDialogItemDto> items,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(requestId);
        ArgumentNullException.ThrowIfNull(items);
        SyncDbWorkspaceFromContext();

        var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
        if (sessionIdError is not null)
            throw new ArgumentException(sessionIdError, nameof(sessionId));
        var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(requestId);
        if (requestIdError is not null)
            throw new ArgumentException(requestIdError, nameof(requestId));

        // BUG-SESSIONLOG-WS-001..004: child sets carry no workspace query filter,
        // so isolation comes from the explicit parent-session predicate here.
        var currentWorkspaceId = _db.CurrentWorkspaceId;
        var entry = await _db.SessionLogTurns
            .Include(e => e.ProcessingDialog)
            .FirstOrDefaultAsync(e =>
                e.SessionLog!.SourceType == sourceType
                && e.SessionLog.SessionId == sessionId
                && e.SessionLog.WorkspaceId == currentWorkspaceId
                && e.RequestId == requestId, cancellationToken)
            .ConfigureAwait(false)
            ?? throw new InvalidOperationException(
                $"Entry not found: {sourceType}/{sessionId}/{requestId}");

        var nextOrdinal = entry.ProcessingDialog.Count > 0
            ? entry.ProcessingDialog.Max(p => p.Ordinal) + 1
            : 0;

        var workspaceId = ResolveWorkspaceId();
        foreach (var item in items)
        {
            entry.ProcessingDialog.Add(new SessionLogProcessingDialogEntity
            {
                Ordinal = nextOrdinal++,
                Timestamp = ParseDateTimeOffset(item.Timestamp) ?? DateTimeOffset.UtcNow,
                Role = item.Role ?? "model",
                Content = item.Content ?? string.Empty,
                Category = item.Category,
                WorkspaceId = workspaceId
            });
        }

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        _logger.LogDebug("Appended {Count} dialog items to {SourceType}/{SessionId}/{RequestId}",
            items.Count, sourceType, sessionId, requestId);
        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return entry.ProcessingDialog.Count;
    }

public async Task<int> RepairWorkspaceStampsAsync(bool dryRun = false, CancellationToken cancellationToken = default)
    {
        SyncDbWorkspaceFromContext();
        var sessions = await _db.SessionLogs
            .IgnoreQueryFilters()
            .Include(s => s.Turns)
                .ThenInclude(t => t.Actions)
            .Include(s => s.Turns)
                .ThenInclude(t => t.Tags)
            .Include(s => s.Turns)
                .ThenInclude(t => t.ContextItems)
            .Include(s => s.Turns)
                .ThenInclude(t => t.ProcessingDialog)
            .Include(s => s.Turns)
                .ThenInclude(t => t.Commits)
                    .ThenInclude(c => c.Files)
            .Include(s => s.Turns)
                .ThenInclude(t => t.StringListItems)
            .AsSplitQuery()
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);

        var changed = 0;
        foreach (var session in sessions)
        {
            var workspaceId = session.WorkspaceId;
            foreach (var turn in session.Turns)
            {
                changed += Restamp(turn.WorkspaceId, workspaceId, value => turn.WorkspaceId = value);
                foreach (var action in turn.Actions)
                    changed += Restamp(action.WorkspaceId, workspaceId, value => action.WorkspaceId = value);
                foreach (var tag in turn.Tags)
                    changed += Restamp(tag.WorkspaceId, workspaceId, value => tag.WorkspaceId = value);
                foreach (var context in turn.ContextItems)
                    changed += Restamp(context.WorkspaceId, workspaceId, value => context.WorkspaceId = value);
                foreach (var dialog in turn.ProcessingDialog)
                    changed += Restamp(dialog.WorkspaceId, workspaceId, value => dialog.WorkspaceId = value);
                foreach (var commit in turn.Commits)
                    changed += Restamp(commit.WorkspaceId, workspaceId, value => commit.WorkspaceId = value);
                foreach (var stringItem in turn.StringListItems)
                    changed += Restamp(stringItem.WorkspaceId, workspaceId, value => stringItem.WorkspaceId = value);
            }
        }

        if (changed > 0 && !dryRun)
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        else if (dryRun)
            _db.ChangeTracker.Clear();

        return changed;

        static int Restamp(string current, string workspaceId, Action<string> setWorkspaceId)
        {
            if (string.Equals(current, workspaceId, StringComparison.Ordinal))
                return 0;

            setWorkspaceId(workspaceId);
            return 1;
        }
    }

public async Task<long> UpsertTurnAsync(string sourceType, string sessionId, UnifiedRequestEntryDto turn, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(turn);
        SyncDbWorkspaceFromContext();

        var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
        if (sessionIdError is not null)
            throw new ArgumentException(sessionIdError, nameof(sessionId));

        var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(turn.RequestId);
        if (requestIdError is not null)
            throw new ArgumentException(requestIdError, nameof(turn));

        var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
            ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

        var existingTurn = session.Turns.FirstOrDefault(t => t.RequestId == turn.RequestId);
        SessionLogTurnEntity persistedTurn;

        ValidateWorkspaceAttribution(turn, existingTurn);

        if (existingTurn is null)
        {
            ApplyTurnContext(turn, isImport: false, sessionDto: null, session);
            persistedTurn = MapSingleEntry(turn);
            session.Turns.Add(persistedTurn);
        }
        else
        {
            SessionLogTurnContextValidator.ValidateIfSupplied(turn.PlanFile, turn.TodoId);
            if (turn.PlanFile is not null)
                turn.PlanFile = SessionLogTurnContextValidator.ValidatePlanFile(turn.PlanFile, required: true);
            if (turn.TodoId is not null)
                turn.TodoId = SessionLogTurnContextValidator.ValidateTodoId(turn.TodoId, required: true);
            UpdateEntryFromDto(existingTurn, turn, mergeOmittedFields: true);
            persistedTurn = existingTurn;
        }

        ValidateTerminalTurnCompliance(MapTurnEntityToDto(persistedTurn), session.SourceType);

        // BUG-SESSIONLOG-WS-002: the turn and its children inherit the PARENT
        // session's stamp; the ambient workspace never re-stamps the session here.
        StampTurnChildren(persistedTurn, session.WorkspaceId);

        RefreshSessionSummaryFromTurns(session);

        try
        {
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        }
        catch (DbUpdateException ex) when (IsSessionLogTurnUniqueRace(ex))
        {
            // TEST-MCP-SESSIONLIFE-005: two first inserts of the same request id.
            // Retry once as an update of the row that won the race.
            _logger.LogWarning(
                "UNIQUE constraint race for turn {SourceType}/{SessionId}/{RequestId}, retrying as update",
                sourceType,
                sessionId,
                turn.RequestId);
            _db.ChangeTracker.Clear();

            session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
                ?? throw new InvalidOperationException($"Session not found after turn unique race: {sourceType}/{sessionId}");
            var raced = session.Turns.FirstOrDefault(t => t.RequestId == turn.RequestId)
                ?? throw new InvalidOperationException(
                    $"Turn {turn.RequestId} disappeared after UNIQUE constraint failure.",
                    ex);

            SessionLogTurnContextValidator.ValidateIfSupplied(turn.PlanFile, turn.TodoId);
            if (turn.PlanFile is not null)
                turn.PlanFile = SessionLogTurnContextValidator.ValidatePlanFile(turn.PlanFile, required: true);
            if (turn.TodoId is not null)
                turn.TodoId = SessionLogTurnContextValidator.ValidateTodoId(turn.TodoId, required: true);
            UpdateEntryFromDto(raced, turn, mergeOmittedFields: true);
            ValidateTerminalTurnCompliance(MapTurnEntityToDto(raced), session.SourceType);
            StampTurnChildren(raced, session.WorkspaceId);
            RefreshSessionSummaryFromTurns(session);
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
            persistedTurn = raced;
        }

        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return persistedTurn.Id;
    }

public async Task<long> SetSessionTitleAsync(string sourceType, string sessionId, string title, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(title);
        SyncDbWorkspaceFromContext();

        var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
        if (sessionIdError is not null)
            throw new ArgumentException(sessionIdError, nameof(sessionId));

        // TR-MCP-SESSIONLOG-005: dedicated session retitle. Unlike the additive
        // SubmitAsync merge (which the plugin now calls with the title omitted),
        // this explicitly overwrites the session Title so an agent rename sticks.
        var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
            ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

        session.Title = title;
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return session.Id;
    }

public async Task<long> SetTurnTitleAsync(string sourceType, string sessionId, string requestId, string title, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(sourceType);
        ArgumentNullException.ThrowIfNull(sessionId);
        ArgumentNullException.ThrowIfNull(requestId);
        ArgumentNullException.ThrowIfNull(title);
        SyncDbWorkspaceFromContext();

        var sessionIdError = SessionLogIdentifierValidator.ValidateSessionId(sessionId, sourceType);
        if (sessionIdError is not null)
            throw new ArgumentException(sessionIdError, nameof(sessionId));

        var requestIdError = SessionLogIdentifierValidator.ValidateRequestId(requestId);
        if (requestIdError is not null)
            throw new ArgumentException(requestIdError, nameof(requestId));

        // TR-MCP-SESSIONLOG-005: dedicated turn retitle. Explicitly overwrites the
        // turn QueryTitle without the reset-omitted-scalars semantics of
        // ReplaceTurnAsync, so an agent-refined title survives incidental submits.
        var session = await FindExistingSessionAsync(sourceType, sessionId, cancellationToken).ConfigureAwait(false)
            ?? throw new InvalidOperationException($"Session not found: {sourceType}/{sessionId}");

        var turn = session.Turns.FirstOrDefault(t => t.RequestId == requestId)
            ?? throw new InvalidOperationException($"Turn not found: {sourceType}/{sessionId}/{requestId}");

        turn.QueryTitle = title;
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        await PublishChangeSafeAsync(
            ChangeEventActions.Updated,
            $"{sourceType}/{sessionId}",
            $"mcp://workspace/sessionlog/{sourceType}/{sessionId}",
            cancellationToken).ConfigureAwait(false);

        return turn.Id;
    }

public async Task<int> RunAsync(CancellationToken cancellationToken = default, string? userProfilePath = null)
    {
        var turns = await _db.SessionLogTurns
            .Include(t => t.Actions)
            .Include(t => t.Tags)
            .Include(t => t.ContextItems)
            .Include(t => t.ProcessingDialog)
            .Include(t => t.StringListItems)
            .Include(t => t.SessionLog)
            .Where(t => t.PlanFile == SessionLogTurnContextValidator.NoneSentinel
                || t.TodoId == SessionLogTurnContextValidator.NoneSentinel)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);

        var changed = 0;
        foreach (var turn in turns)
        {
            var workspace = string.IsNullOrWhiteSpace(turn.WorkspaceId) ? null : turn.WorkspaceId;
            var extracted = _extractor.Extract(
                turn,
                workspace,
                userProfilePath,
                agentSessionId: turn.SessionLog?.AgentSessionId,
                agentSessionTranscriptFile: turn.SessionLog?.AgentSessionTranscriptFile);

            var updated = false;
            if (turn.PlanFile == SessionLogTurnContextValidator.NoneSentinel
                && extracted.PlanFile != SessionLogTurnContextValidator.NoneSentinel)
            {
                turn.PlanFile = extracted.PlanFile;
                updated = true;
            }

            if (turn.TodoId == SessionLogTurnContextValidator.NoneSentinel
                && extracted.TodoId != SessionLogTurnContextValidator.NoneSentinel)
            {
                turn.TodoId = extracted.TodoId;
                updated = true;
            }

            if (updated)
                changed++;
        }

        if (changed > 0)
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        _logger.LogInformation("Session-log planFile/todoId backfill updated {Count} turns.", changed);
        return changed;
    }

internal async Task<BootstrapOutcome> BootstrapWorkspaceAsync(WorkspaceConfigEntry entry, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(entry);

        var workspacePath = Path.GetFullPath(entry.WorkspacePath);
        var todoRel = string.IsNullOrWhiteSpace(entry.TodoPath) ? "docs/todo.yaml" : entry.TodoPath;
        var todoAbsolute = Path.IsPathRooted(todoRel)
            ? Path.GetFullPath(todoRel)
            : Path.GetFullPath(Path.Combine(workspacePath, todoRel));
        var dataDirectory = string.IsNullOrWhiteSpace(entry.DataDirectory) ? workspacePath : Path.GetFullPath(entry.DataDirectory);
        var markerPath = Path.Combine(dataDirectory, MarkerFileName);

        if (File.Exists(markerPath))
            return new BootstrapOutcome(workspacePath, BootstrapResult.SkippedMarkerPresent, 0);

        if (!File.Exists(todoAbsolute))
        {
            _logger.LogInformation("TodoBootstrapImporter: '{Workspace}' has no YAML at '{Path}'; no-op.", workspacePath, todoAbsolute);
            return new BootstrapOutcome(workspacePath, BootstrapResult.SkippedMissingYaml, 0);
        }

        await using var scope = _scopeFactory.CreateAsyncScope();
        var ctx = scope.ServiceProvider.GetRequiredService<McpDbContext>();
        ctx.OverrideWorkspaceId(workspacePath);

        if (await ctx.TodoItems.AnyAsync(cancellationToken).ConfigureAwait(false))
        {
            await WriteMarkerAsync(markerPath, "target non-empty", cancellationToken).ConfigureAwait(false);
            return new BootstrapOutcome(workspacePath, BootstrapResult.SkippedWorkspacePopulated, 0);
        }

        var file = await TodoYamlFileSerializer.ReadIfExistsAsync(todoAbsolute, cancellationToken).ConfigureAwait(false);
        if (file is null)
            return new BootstrapOutcome(workspacePath, BootstrapResult.SkippedMissingYaml, 0);

        var importedAtUtc = DateTime.UtcNow.ToString("O");
        var (items, history, metadata) = ProjectEntities(file, importedAtUtc);

        foreach (var item in items)
        {
            ctx.TodoItems.Add(item);
            ctx.TodoItemListItems.AddRange(item.ListItems);
            ctx.TodoItemTasks.AddRange(item.ImplementationTaskRows);
        }

        foreach (var row in history)
            ctx.TodoAuditHistory.Add(row);
        ctx.TodoDocumentMetadata.Add(metadata);
        ctx.TodoDocumentNotes.AddRange(metadata.Notes);
        ctx.TodoCompletedGroups.AddRange(metadata.CompletedGroups);

        await ctx.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        await WriteMarkerAsync(markerPath, $"imported items={items.Count}", cancellationToken).ConfigureAwait(false);

        _logger.LogInformation(
            "TodoBootstrapImporter: workspace '{Workspace}' bootstrapped {Items} items from '{Path}'.",
            workspacePath, items.Count, todoAbsolute);
        return new BootstrapOutcome(workspacePath, BootstrapResult.Imported, items.Count);
    }

public async Task<ToolMutationResult> InstallAsync(string bucketName, string toolName, string? workspacePath = null, CancellationToken ct = default)
    {
        var name = (bucketName ?? "").Trim().ToLowerInvariant();
        var bucket = await GetVisibleBucketsQuery().AsNoTracking().FirstOrDefaultAsync(b => b.Name == name, ct).ConfigureAwait(false);
        if (bucket is null)
            return new ToolMutationResult(false, $"Bucket '{name}' not found.");

        var manifests = await FetchManifestsAsync(bucket, ct).ConfigureAwait(false);
        if (manifests is null)
            return new ToolMutationResult(false, $"Failed to read manifests from {bucket.Owner}/{bucket.Repo}.");

        var manifest = manifests.FirstOrDefault(m => string.Equals(m.Name, toolName, StringComparison.OrdinalIgnoreCase));
        if (manifest is null)
            return new ToolMutationResult(false, $"Tool '{toolName}' not found in bucket '{name}'.");

        // Create via the registry service (handles uniqueness, normalization).
        var result = await _toolRegistry.CreateAsync(new ToolCreateRequest(
            manifest.Name,
            manifest.Description,
            manifest.Tags,
            manifest.ParameterSchema,
            manifest.CommandTemplate,
            workspacePath), ct).ConfigureAwait(false);

        if (!result.Success)
            return result;

        // Stamp the bucket provenance.
        var entity = await _db.ToolDefinitions.FirstOrDefaultAsync(t => t.Id == result.Tool!.Id, ct).ConfigureAwait(false);
        if (entity is not null)
        {
            entity.BucketName = name;
            await _db.SaveChangesAsync(ct).ConfigureAwait(false);
        }

        _logger.LogInformation("Installed tool '{Tool}' from bucket '{Bucket}'", manifest.Name, name);
        return result;
    }

public async Task<BucketSyncResult> SyncAsync(string bucketName, CancellationToken ct = default)
    {
        var name = (bucketName ?? "").Trim().ToLowerInvariant();
        var bucket = await GetVisibleBucketsQuery().FirstOrDefaultAsync(b => b.Name == name, ct).ConfigureAwait(false);
        if (bucket is null)
            return new BucketSyncResult(false, $"Bucket '{name}' not found.");

        var manifests = await FetchManifestsAsync(bucket, ct).ConfigureAwait(false);
        if (manifests is null)
            return new BucketSyncResult(false, $"Failed to read manifests from {bucket.Owner}/{bucket.Repo}.");

        var installed = await _db.ToolDefinitions
            .Include(t => t.Tags)
            .Where(t => t.BucketName == name)
            .ToListAsync(ct).ConfigureAwait(false);

        int updated = 0, unchanged = 0;
        var manifestByName = manifests.ToDictionary(m => m.Name, StringComparer.OrdinalIgnoreCase);

        foreach (var tool in installed)
        {
            if (!manifestByName.TryGetValue(tool.Name, out var manifest))
            {
                unchanged++;
                continue;
            }

            var changed = false;
            if (tool.Description != manifest.Description) { tool.Description = manifest.Description; changed = true; }
            if (tool.ParameterSchema != manifest.ParameterSchema) { tool.ParameterSchema = manifest.ParameterSchema; changed = true; }
            if (tool.CommandTemplate != manifest.CommandTemplate) { tool.CommandTemplate = manifest.CommandTemplate; changed = true; }

            var currentTags = tool.Tags.Select(t => t.Tag).OrderBy(t => t).ToList();
            var newTags = manifest.Tags.Select(t => t.Trim().ToLowerInvariant()).OrderBy(t => t).Distinct().ToList();
            if (!currentTags.SequenceEqual(newTags))
            {
                tool.Tags.Clear();
                foreach (var tag in newTags)
                    tool.Tags.Add(new ToolDefinitionTagEntity { Tag = tag });
                changed = true;
            }

            if (changed)
            {
                tool.DateTimeModified = DateTimeOffset.UtcNow;
                updated++;
            }
            else
            {
                unchanged++;
            }
        }

        bucket.DateTimeLastSynced = DateTimeOffset.UtcNow;
        await _db.SaveChangesAsync(ct).ConfigureAwait(false);
        await PublishChangeSafeAsync(ChangeEventActions.Updated, name, ct).ConfigureAwait(false);

        _logger.LogInformation("Bucket sync '{Name}': {Updated} updated, {Unchanged} unchanged", name, updated, unchanged);
        return new BucketSyncResult(true, Updated: updated, Unchanged: unchanged);
    }

public async Task<BucketMutationResult> AddBucketAsync(BucketAddRequest request, CancellationToken ct = default)
    {
        var name = (request.Name ?? "").Trim().ToLowerInvariant();
        if (string.IsNullOrEmpty(name))
