            }
        }

public async Task<WikiDumpImportResult> ImportAsync(WikiDumpImportRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        cancellationToken.ThrowIfCancellationRequested();
        if (IsUnsafePath(request.DumpPath) || IsUnsafePath(request.DestinationWorkspacePath))
            return Fail("unsafe_path", "Dump or destination path is unsafe.");

        var dumpFile = ResolveDumpFile(request.DumpPath);
        if (dumpFile is null)
            return Fail("malformed_dump", "Dump path does not contain mcp-wiki-dump.json.");

        string json;
        try
        {
            json = await File.ReadAllTextAsync(dumpFile, cancellationToken).ConfigureAwait(false);
            JsonSerializer.Deserialize<WikiDumpDocument>(json, JsonOptions);
        }
        catch (JsonException)
        {
            return Fail("malformed_dump", "Dump JSON is malformed.");
        }

        var dump = JsonSerializer.Deserialize<WikiDumpDocument>(json, JsonOptions);
        if (dump is null)
            return Fail("malformed_dump", "Dump JSON is malformed.");
        if (!string.Equals(dump.SchemaVersion, WikiDumpDefaults.SchemaVersion, StringComparison.Ordinal))
            return Fail("version_mismatch", "Dump schemaVersion is not mcp-wiki-dump/v1.");
        if (dump.Tables.Count == 0)
            return Fail("missing_tables", "Dump tables[] is missing.");

        var expected = ComputeSha256(dump);
        if (!string.IsNullOrWhiteSpace(dump.Sha256) && !string.Equals(dump.Sha256, expected, StringComparison.OrdinalIgnoreCase))
            return Fail("hash_mismatch", "Dump sha256 does not match canonical bytes.");

        var destination = Path.GetFullPath(request.DestinationWorkspacePath);
        var diagnostics = new List<string>();
        var created = new List<string>();
        foreach (var todo in dump.Todos)
        {
            var exists = await _db.TodoItems.AnyAsync(item => item.Id == todo.Id, cancellationToken).ConfigureAwait(false);
            if (exists)
                continue;
            _db.TodoItems.Add(new TodoItemEntity
            {
                Id = todo.Id,
                Title = todo.Title,
                Section = todo.Section,
                Priority = todo.Priority,
                Done = todo.Done,
                WorkspaceId = destination,
            });
            created.Add(todo.Id);
        }

        foreach (var link in dump.TodoRequirementLinks)
        {
            var exists = await _db.TodoRequirementLinks.AnyAsync(
                item => item.TodoId == link.TodoId && item.RequirementId == link.RequirementId,
                cancellationToken).ConfigureAwait(false);
            if (exists)
                continue;
            _db.TodoRequirementLinks.Add(new TodoRequirementLinkEntity
            {
                WorkspaceId = destination,
                TodoId = link.TodoId,
                RequirementKind = link.RequirementKind,
                RequirementId = link.RequirementId,
                CreatedAtUtc = _time.GetUtcNow(),
            });
        }

        if (created.Count > 0 || dump.TodoRequirementLinks.Count > 0)
            await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        string? archive = null;
        var todoYaml = request.TodoYamlPath;
        if (string.IsNullOrWhiteSpace(todoYaml))
        {
            var sibling = Path.Combine(Path.GetDirectoryName(dumpFile) ?? destination, "todo.yaml");
            if (File.Exists(sibling))
                todoYaml = sibling;
            var destYaml = Path.Combine(destination, "docs", "todo.yaml");
            if (File.Exists(destYaml))
                todoYaml = destYaml;
        }

        if (!string.IsNullOrWhiteSpace(todoYaml) && File.Exists(todoYaml))
        {
            diagnostics.Add("dump_wins_over_todo_yaml: " + dumpFile + " | " + todoYaml);
            var archiveDir = Path.Combine(destination, ".mcpServer", "archive", "todo-yaml");
            Directory.CreateDirectory(archiveDir);
            archive = Path.Combine(archiveDir, "todo.yaml");
            File.Copy(todoYaml, archive, overwrite: true);
        }

        return new WikiDumpImportResult
        {
            Success = true,
            CreatedTodoIds = created,
            Diagnostics = diagnostics,
            TodoYamlArchivePath = archive,
        };
    }

private async Task<WorkspaceMutationResult> CreateDatabaseAsync(WorkspaceCreateRequest request, CancellationToken ct)
    {
        var normalized = NormalizePath(request.WorkspacePath);
        if (string.IsNullOrWhiteSpace(normalized))
            return new WorkspaceMutationResult(false, "WorkspacePath is required.");

        await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
            var existing = await _db!.Workspaces
                .IgnoreQueryFilters()
                .Include(w => w.BannedItems)
                .SingleOrDefaultAsync(w => w.WorkspaceId == normalized || w.WorkspacePath == normalized, ct)
                .ConfigureAwait(false);

            if (existing is { IsDeleted: false })
                return new WorkspaceMutationResult(false, $"Workspace already registered: {normalized}");

            var entry = CreateConfigEntry(request, normalized);
            WorkspaceEntity entity;
            if (existing is null)
            {
                entity = ToEntity(entry);
                _db.Workspaces.Add(entity);
            }
            else
            {
                ApplyConfigEntry(existing, entry);
                existing.IsDeleted = false;
                existing.DeletedAtUtc = null;
                existing.DeletedBy = null;
                existing.DeleteReason = null;
                entity = existing;
            }

            await using var transaction = await _db.Database.BeginTransactionAsync(ct).ConfigureAwait(false);
            try
            {
                await _db.SaveChangesAsync(ct).ConfigureAwait(false);
                var importFailure = await TryImportDumpAsync(request.DumpPath, normalized, ct).ConfigureAwait(false);
                if (importFailure is not null)
                {
                    await transaction.RollbackAsync(ct).ConfigureAwait(false);
                    _db.ChangeTracker.Clear();
                    return importFailure;
                }

                await transaction.CommitAsync(ct).ConfigureAwait(false);
            }
            catch
            {
                await transaction.RollbackAsync(ct).ConfigureAwait(false);
                _db.ChangeTracker.Clear();
                throw;
            }

            await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
            _logger.LogInformation("Workspace created: {Name} at {Path}", entity.Name, entity.WorkspacePath);
            await PublishChangeSafeAsync(ChangeEventActions.Created, normalized, ct).ConfigureAwait(false);
            return new WorkspaceMutationResult(true, Workspace: await ToDtoAsync(entity, ct).ConfigureAwait(false));
        }
        finally
        {
            s_writeLock.Release();
        }
    }

private async Task<WorkspaceMutationResult> UpdateDatabaseAsync(string workspacePath, WorkspaceUpdateRequest request, CancellationToken ct)
    {
        var normalized = NormalizePath(workspacePath);
        await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
            var entity = await FindActiveWorkspaceAsync(normalized, ct).ConfigureAwait(false);
            if (entity is null)
                return new WorkspaceMutationResult(false, $"Workspace not found: {normalized}");

            ApplyUpdate(entity, request, normalized);
            await _db!.SaveChangesAsync(ct).ConfigureAwait(false);
            await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
            _logger.LogInformation("Workspace updated: {Name} at {Path}", entity.Name, entity.WorkspacePath);
            await PublishChangeSafeAsync(ChangeEventActions.Updated, normalized, ct).ConfigureAwait(false);
            return new WorkspaceMutationResult(true, Workspace: await ToDtoAsync(entity, ct).ConfigureAwait(false));
        }
        finally
        {
            s_writeLock.Release();
        }
    }

private async Task<WorkspaceMutationResult> DeleteDatabaseAsync(string workspacePath, CancellationToken ct)
    {
        var normalized = NormalizePath(workspacePath);
        await s_writeLock.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            await EnsureBootstrappedAsync(ct).ConfigureAwait(false);
            var entity = await FindActiveWorkspaceAsync(normalized, ct).ConfigureAwait(false);
            if (entity is null)
                return new WorkspaceMutationResult(false, $"Workspace not found: {normalized}");

            var dto = await ToDtoAsync(entity, ct).ConfigureAwait(false);
            entity.IsDeleted = true;
            entity.DeletedAtUtc = DateTimeOffset.UtcNow;
            entity.DeletedBy = nameof(WorkspaceService);
            entity.DeleteReason = "workspace_delete";
            entity.DateTimeModified = entity.DeletedAtUtc.Value;
            await _db!.SaveChangesAsync(ct).ConfigureAwait(false);
            await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
            _logger.LogInformation("Workspace soft-deleted: {Name} at {Path}", dto.Name, dto.WorkspacePath);
            await PublishChangeSafeAsync(ChangeEventActions.Deleted, normalized, ct).ConfigureAwait(false);
            return new WorkspaceMutationResult(true, Workspace: dto);
        }
        finally
        {
            s_writeLock.Release();
        }
    }

private async Task EnsureBootstrappedAsync(CancellationToken ct)
    {
        if (_db is null)
            return;

        if (!await _db.Workspaces.IgnoreQueryFilters().AnyAsync(w => w.WorkspaceId == string.Empty, ct).ConfigureAwait(false))
        {
            _db.Workspaces.Add(new WorkspaceEntity
            {
                WorkspaceId = string.Empty,
                WorkspacePath = string.Empty,
                Name = "global",
                TodoPath = DefaultTodoPath,
                IsEnabled = true,
                DateTimeCreated = DateTimeOffset.UtcNow,
                DateTimeModified = DateTimeOffset.UtcNow,
            });
        }

        if (await _db.Workspaces.AnyAsync(w => w.WorkspaceId != string.Empty, ct).ConfigureAwait(false))
        {
            if (_db.ChangeTracker.HasChanges())
                await _db.SaveChangesAsync(ct).ConfigureAwait(false);
            return;
        }

        foreach (var entry in ReadAll())
        {
            var normalized = NormalizePath(entry.WorkspacePath);
            if (string.IsNullOrWhiteSpace(normalized))
                continue;

            if (_db.Workspaces.Local.Any(w => string.Equals(w.WorkspaceId, normalized, StringComparison.OrdinalIgnoreCase)))
                continue;

            entry.WorkspacePath = normalized;
            _db.Workspaces.Add(ToEntity(entry));
        }

        if (_db.ChangeTracker.HasChanges())
        {
            await _db.SaveChangesAsync(ct).ConfigureAwait(false);
            await WriteProjectionFromDatabaseAsync(ct).ConfigureAwait(false);
        }
    }

public async Task<Result<UseCaseFlowDto>> HandleAsync(AddUseCaseFlowCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var workspaceId = UseCaseCqrsHelpers.ResolveWorkspaceId(db, workspaceContext, command.WorkspacePath);
            var flowType = UseCaseConstants.CanonicalizeFlowType(command.Request.FlowType);
            if (flowType is null)
                return Result<UseCaseFlowDto>.Failure("FlowType must be Basic, Alternative, or Exception.");

            var useCase = await db.UseCases
                .FirstOrDefaultAsync(u => u.UseCaseId == command.UseCaseId, context.CancellationToken)
                .ConfigureAwait(false);
            if (useCase is null)
                return Result<UseCaseFlowDto>.Failure($"Use case '{command.UseCaseId}' was not found.");

            int sequence;
            if (command.Request.SequenceNumber is int explicitSequence)
            {
                sequence = explicitSequence;
            }
            else
            {
                var max = await db.UseCaseFlows
                    .Where(f => f.UseCaseId == command.UseCaseId)
                    .Select(f => (int?)f.SequenceNumber)
                    .MaxAsync(context.CancellationToken)
                    .ConfigureAwait(false);
                sequence = (max ?? 0) + 1;
            }

            var flow = new UseCaseFlowEntity
            {
                WorkspaceId = workspaceId,
                UseCaseId = command.UseCaseId,
                FlowType = flowType,
                Name = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Name),
                SequenceNumber = sequence,
            };
            db.UseCaseFlows.Add(flow);
            useCase.UpdatedAtUtc = DateTimeOffset.UtcNow;
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            return Result<UseCaseFlowDto>.Success(UseCaseCqrsHelpers.ToFlowDto(flow));
        }
        catch (Exception ex)
        {
            return Result<UseCaseFlowDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<UseCaseStepDto>> HandleAsync(AddUseCaseStepCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var workspaceId = UseCaseCqrsHelpers.ResolveWorkspaceId(db, workspaceContext, command.WorkspacePath);

            if (string.IsNullOrWhiteSpace(command.Request.Action))
                return Result<UseCaseStepDto>.Failure("Action is required.");

            var flow = await db.UseCaseFlows
                .FirstOrDefaultAsync(
                    f => f.FlowId == command.FlowId && f.UseCaseId == command.UseCaseId,
                    context.CancellationToken)
                .ConfigureAwait(false);
            if (flow is null)
                return Result<UseCaseStepDto>.Failure(
                    $"Flow '{command.FlowId}' was not found on use case '{command.UseCaseId}'.");

            if (command.Request.ActorId is long actorId)
            {
                var actorExists = await db.Actors
                    .AnyAsync(a => a.ActorId == actorId, context.CancellationToken)
                    .ConfigureAwait(false);
                if (!actorExists)
                    return Result<UseCaseStepDto>.Failure($"Actor '{actorId}' was not found.");
            }

            int stepNumber;
            if (command.Request.StepNumber is int explicitStep)
            {
                stepNumber = explicitStep;
            }
            else
            {
                var max = await db.UseCaseSteps
                    .Where(s => s.FlowId == command.FlowId)
                    .Select(s => (int?)s.StepNumber)
                    .MaxAsync(context.CancellationToken)
                    .ConfigureAwait(false);
                stepNumber = (max ?? 0) + 1;
            }

            var step = new UseCaseStepEntity
            {
                WorkspaceId = workspaceId,
                FlowId = command.FlowId,
                StepNumber = stepNumber,
                ActorId = command.Request.ActorId,
                Action = command.Request.Action.Trim(),
                SystemResponse = UseCaseCqrsHelpers.NormalizeOptional(command.Request.SystemResponse),
                DataEntities = UseCaseCqrsHelpers.NormalizeOptional(command.Request.DataEntities),
            };
            db.UseCaseSteps.Add(step);

            var useCase = await db.UseCases
                .FirstOrDefaultAsync(u => u.UseCaseId == command.UseCaseId, context.CancellationToken)
                .ConfigureAwait(false);
            if (useCase is not null)
                useCase.UpdatedAtUtc = DateTimeOffset.UtcNow;

            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            if (step.ActorId is not null)
            {
                await db.Entry(step).Reference(s => s.Actor).LoadAsync(context.CancellationToken).ConfigureAwait(false);
            }

            return Result<UseCaseStepDto>.Success(UseCaseCqrsHelpers.ToStepDto(step));
        }
        catch (Exception ex)
        {
            return Result<UseCaseStepDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<UseCaseActorDto>> HandleAsync(AttachUseCaseActorCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var workspaceId = UseCaseCqrsHelpers.ResolveWorkspaceId(db, workspaceContext, command.WorkspacePath);
            var actorType = UseCaseConstants.CanonicalizeActorType(command.Request.Type);
            if (actorType is null)
                return Result<UseCaseActorDto>.Failure("Actor Type must be Primary, Secondary, System, or External.");

            var useCase = await db.UseCases
                .FirstOrDefaultAsync(u => u.UseCaseId == command.UseCaseId, context.CancellationToken)
                .ConfigureAwait(false);
            if (useCase is null)
                return Result<UseCaseActorDto>.Failure($"Use case '{command.UseCaseId}' was not found.");

            ActorEntity actor;
            if (command.Request.ActorId is long actorId)
            {
                var existing = await db.Actors
                    .FirstOrDefaultAsync(a => a.ActorId == actorId, context.CancellationToken)
                    .ConfigureAwait(false);
                if (existing is null)
                    return Result<UseCaseActorDto>.Failure($"Actor '{actorId}' was not found.");
                actor = existing;
            }
            else
            {
                var name = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Name);
                if (name is null)
                    return Result<UseCaseActorDto>.Failure("Actor Name is required when ActorId is not provided.");
                if (name.Length > 100)
                    return Result<UseCaseActorDto>.Failure("Actor Name must be 100 characters or fewer.");

                var existingByName = await db.Actors
                    .FirstOrDefaultAsync(a => a.Name == name, context.CancellationToken)
                    .ConfigureAwait(false);
                if (existingByName is not null)
                {
                    actor = existingByName;
                }
                else
                {
                    actor = new ActorEntity
                    {
                        WorkspaceId = workspaceId,
                        Name = name,
                        Description = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Description),
                        Type = actorType,
                    };
                    db.Actors.Add(actor);
                    await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);
                }
            }

            var join = await db.UseCaseActors
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(
                    a => a.WorkspaceId == workspaceId
                         && a.UseCaseId == command.UseCaseId
                         && a.ActorId == actor.ActorId,
                    context.CancellationToken)
                .ConfigureAwait(false);

            if (join is null)
            {
                join = new UseCaseActorEntity
                {
                    WorkspaceId = workspaceId,
                    UseCaseId = command.UseCaseId,
                    ActorId = actor.ActorId,
                    IsPrimary = command.Request.IsPrimary,
                };
                db.UseCaseActors.Add(join);
            }
            else
            {
                UseCaseCqrsHelpers.ClearSoftDelete(db, join);
                join.IsPrimary = command.Request.IsPrimary;
            }

            if (command.Request.IsPrimary)
            {
                var others = await db.UseCaseActors
                    .Where(a => a.UseCaseId == command.UseCaseId && a.ActorId != actor.ActorId && a.IsPrimary)
                    .ToListAsync(context.CancellationToken)
                    .ConfigureAwait(false);
                foreach (var other in others)
                    other.IsPrimary = false;
            }

            useCase.UpdatedAtUtc = DateTimeOffset.UtcNow;
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            return Result<UseCaseActorDto>.Success(new UseCaseActorDto
            {
                ActorId = actor.ActorId,
                UseCaseId = command.UseCaseId,
                Name = actor.Name,
                Description = actor.Description,
                Type = actor.Type,
                IsPrimary = join.IsPrimary,
            });
        }
        catch (Exception ex)
        {
            return Result<UseCaseActorDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<UseCaseDetailDto>> HandleAsync(CreateUseCaseCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var workspaceId = UseCaseCqrsHelpers.ResolveWorkspaceId(db, workspaceContext, command.WorkspacePath);
            var title = UseCaseCqrsHelpers.ValidateTitle(command.Request.Title, out var titleError);
            if (title is null)
                return Result<UseCaseDetailDto>.Failure(titleError!);

            string? linkType = null;
            string? frId = UseCaseCqrsHelpers.NormalizeOptional(command.Request.FrId);
            if (frId is not null)
            {
                linkType = UseCaseConstants.CanonicalizeLinkType(command.Request.LinkType);
                var frError = await UseCaseCqrsHelpers.ValidateFrExistsAsync(db, workspaceId, frId, context.CancellationToken)
                    .ConfigureAwait(false);
                if (frError is not null)
                    return Result<UseCaseDetailDto>.Failure(frError);
            }

            var now = DateTimeOffset.UtcNow;
            var entity = new UseCaseEntity
            {
                WorkspaceId = workspaceId,
                Title = title,
                BriefDescription = UseCaseCqrsHelpers.NormalizeOptional(command.Request.BriefDescription),
                Precondition = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Precondition),
                Postcondition = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Postcondition),
                Scope = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Scope),
                Priority = command.Request.Priority,
                CreatedAtUtc = now,
                UpdatedAtUtc = now,
            };

            db.UseCases.Add(entity);
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            if (frId is not null)
            {
                db.UseCaseFrLinks.Add(new UseCaseFrLinkEntity
                {
                    WorkspaceId = workspaceId,
                    UseCaseId = entity.UseCaseId,
                    FrId = frId,
                    FrKind = UseCaseConstants.FrKind,
                    LinkType = linkType!,
                    LinkOrder = command.Request.LinkOrder,
                    Notes = UseCaseCqrsHelpers.NormalizeOptional(command.Request.Notes),
                    CreatedAtUtc = now,
                });
            }

            var initialSteps = command.Request.InitialSteps;
            var createFlow = command.Request.CreateBasicFlow || (initialSteps is { Count: > 0 });
            if (createFlow)
            {
                var flow = new UseCaseFlowEntity
                {
                    WorkspaceId = workspaceId,
                    UseCaseId = entity.UseCaseId,
                    FlowType = "Basic",
                    Name = "Basic",
                    SequenceNumber = 1,
                };
                db.UseCaseFlows.Add(flow);
                await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

                if (initialSteps is { Count: > 0 })
                {
                    var stepNumber = 1;
                    foreach (var stepReq in initialSteps)
                    {
                        if (string.IsNullOrWhiteSpace(stepReq.Action))
                            return Result<UseCaseDetailDto>.Failure("Initial step Action is required.");

                        db.UseCaseSteps.Add(new UseCaseStepEntity
                        {
                            WorkspaceId = workspaceId,
                            FlowId = flow.FlowId,
                            StepNumber = stepReq.StepNumber ?? stepNumber,
                            ActorId = stepReq.ActorId,
                            Action = stepReq.Action.Trim(),
                            SystemResponse = UseCaseCqrsHelpers.NormalizeOptional(stepReq.SystemResponse),
                            DataEntities = UseCaseCqrsHelpers.NormalizeOptional(stepReq.DataEntities),
                        });
                        stepNumber++;
                    }
                }
            }

            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            var loaded = await UseCaseCqrsHelpers.LoadAggregateAsync(db, entity.UseCaseId, context.CancellationToken)
                .ConfigureAwait(false);
            return Result<UseCaseDetailDto>.Success(UseCaseCqrsHelpers.ToDetailDto(loaded!));
        }
        catch (Exception ex)
        {
            return Result<UseCaseDetailDto>.Failure(ex.Message, ex);
        }
    }

