private static async Task RunPostgreSqlAsync(
        McpDatabaseRuntimeOptions runtimeOptions,
        McpDatabaseEncryptionTransitionOptions options,
        McpDatabaseEncryptionTransitionReport report,
        bool targetEncrypted,
        CancellationToken cancellationToken)
    {
        var dumpToolPath = options.PostgreSqlDumpToolPath ?? "pg_dump.exe";
        if (options.Execute && string.IsNullOrWhiteSpace(options.BackupPath))
        {
            throw new InvalidOperationException(
                "PostgreSQL transitions require --backup-path so pg_dump can capture rollback material before any table rewrite occurs.");
        }

        report.AddStep("Capture a pg_dump backup", "Run pg_dump in custom format before rewriting any application tables so rollback remains possible.", $"{dumpToolPath} -Fc -f <backup-path> -d <configured-connection-string>");
        report.AddStep(
            "Rewrite application tables",
            targetEncrypted
                ? "Rewrite each public application table from heap to tde_heap and run SELECT count(*) after each rewrite."
                : "Rewrite each encrypted public application table from tde_heap back to heap and run SELECT count(*) after each rewrite.",
            targetEncrypted
                ? "ALTER TABLE \"public\".\"<table>\" SET ACCESS METHOD tde_heap;\nSELECT count(*) FROM \"public\".\"<table>\";"
                : "ALTER TABLE \"public\".\"<table>\" SET ACCESS METHOD heap;\nSELECT count(*) FROM \"public\".\"<table>\";");
        report.AddStep("Verify final table state", "Use pg_tde_is_encrypted(...) to confirm every application table reached the requested state.", "SELECT schemaname, tablename, pg_tde_is_encrypted(format('%I.%I', schemaname, tablename)::regclass) FROM pg_tables WHERE schemaname = 'public' AND tablename <> '__EFMigrationsHistory';");

        if (!options.Execute)
        {
            report.Summary = targetEncrypted ? "PostgreSQL enable transition plan generated." : "PostgreSQL disable transition plan generated.";
            return;
        }

        if (targetEncrypted
            && (string.IsNullOrWhiteSpace(runtimeOptions.EncryptionOptions.PostgreSqlKeyProvider)
                || string.IsNullOrWhiteSpace(runtimeOptions.EncryptionOptions.PostgreSqlPrincipalKey)))
        {
            throw new InvalidOperationException(
                "PostgreSQL enable transitions require pg_tde key-provider and principal-key configuration before table rewrites can begin.");
        }

        await RunProcessAsync(dumpToolPath, ["-Fc", "-f", Path.GetFullPath(options.BackupPath!), "-d", runtimeOptions.ProviderOptions.ConnectionString], null, cancellationToken).ConfigureAwait(false);

        await using var dbContext = CreateDbContext(runtimeOptions.ProviderOptions);
        await using var connection = dbContext.Database.GetDbConnection();
        if (connection.State != ConnectionState.Open)
        {
            await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
        }

        var extensionInstalled = await ExecuteScalarAsync<bool>(
            connection,
            """
            SELECT EXISTS (
                SELECT 1
                FROM pg_extension
                WHERE extname = 'pg_tde');
            """,
            cancellationToken).ConfigureAwait(false);
        if (!extensionInstalled)
        {
            throw new InvalidOperationException("The connected PostgreSQL database does not expose pg_tde. Provision Percona Server for PostgreSQL with pg_tde before running a transition.");
        }

        var tables = await ReadPostgreSqlTableStatesAsync(connection, cancellationToken).ConfigureAwait(false);
        foreach (var table in tables.Where(t => targetEncrypted ? !t.IsEncrypted : t.IsEncrypted))
        {
            var rewriteSql = targetEncrypted
                ? $"ALTER TABLE {QuotePostgreSqlIdentifier(table.Schema)}.{QuotePostgreSqlIdentifier(table.Table)} SET ACCESS METHOD tde_heap;"
                : $"ALTER TABLE {QuotePostgreSqlIdentifier(table.Schema)}.{QuotePostgreSqlIdentifier(table.Table)} SET ACCESS METHOD heap;";
            await ExecuteNonQueryAsync(connection, rewriteSql, cancellationToken).ConfigureAwait(false);
            await ExecuteScalarAsync<long>(connection, $"SELECT count(*) FROM {QuotePostgreSqlIdentifier(table.Schema)}.{QuotePostgreSqlIdentifier(table.Table)};", cancellationToken).ConfigureAwait(false);
        }

        await ValidateAgainstTargetStateAsync(runtimeOptions, targetEncrypted, cancellationToken).ConfigureAwait(false);
        SetAllStepStatuses(report, "completed");
        report.Summary = targetEncrypted
            ? "PostgreSQL tables were rewritten to pg_tde successfully. Keep the pg_dump backup until the server restarts cleanly with encryption enabled."
            : "PostgreSQL tables were rewritten back to heap successfully. Keep the pg_dump backup until the server restarts cleanly with encryption disabled.";
    }

private static async Task RunSqlServerAsync(
        McpDatabaseRuntimeOptions runtimeOptions,
        McpDatabaseEncryptionTransitionOptions options,
        McpDatabaseEncryptionTransitionReport report,
        bool targetEncrypted,
        CancellationToken cancellationToken)
    {
        if (options.Execute && string.IsNullOrWhiteSpace(options.BackupPath))
        {
            throw new InvalidOperationException("SQL Server transitions require --backup-path because BACKUP DATABASE must run before the TDE state changes.");
        }

        report.AddStep("Capture a copy-only SQL Server backup", "Take a copy-only database backup before changing TDE state so rollback material exists if the transition has to be reversed.", "BACKUP DATABASE [<current-database>] TO DISK = N'<backup-path>' WITH COPY_ONLY, INIT, CHECKSUM;");
        report.AddStep(
            "Validate SQL Server TDE prerequisites",
            targetEncrypted
                ? "Verify that the configured server certificate already exists in master before enabling TDE."
                : "Verify that the database is reachable and that existing TDE state can be queried before disabling TDE.",
            targetEncrypted
                ? "SELECT COUNT(*) FROM master.sys.certificates WHERE name = @certificateName;"
                : "SELECT TOP (1) encryption_state FROM sys.dm_database_encryption_keys WHERE database_id = DB_ID();");
        report.AddStep(
            "Change database TDE state",
            targetEncrypted
                ? "Create the database encryption key if needed, then enable TDE."
                : "Disable TDE and wait for decryption to complete.",
            targetEncrypted
                ? "CREATE DATABASE ENCRYPTION KEY WITH ALGORITHM = AES_256 ENCRYPTION BY SERVER CERTIFICATE [<certificate>];\nALTER DATABASE [<current-database>] SET ENCRYPTION ON;"
                : "ALTER DATABASE [<current-database>] SET ENCRYPTION OFF;");
        report.AddStep("Poll for the final encryption state", targetEncrypted ? "Poll sys.dm_database_encryption_keys until encryption_state reaches 3 (encrypted)." : "Poll sys.dm_database_encryption_keys until the database reports state 1 or no row remains.", "SELECT TOP (1) encryption_state FROM sys.dm_database_encryption_keys WHERE database_id = DB_ID();");
        report.Warnings.Add("SQL Server TDE transitions do not remove certificates or keys automatically. Retain all TDE certificates and private keys for backup and restore compatibility.");

        if (!options.Execute)
        {
            report.Summary = targetEncrypted ? "SQL Server enable transition plan generated." : "SQL Server disable transition plan generated.";
            return;
        }

        await using var dbContext = CreateDbContext(runtimeOptions.ProviderOptions);
        await using var connection = dbContext.Database.GetDbConnection();
        if (connection.State != ConnectionState.Open)
        {
            await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
        }

        var databaseName = await ExecuteScalarAsync<string>(connection, "SELECT DB_NAME();", cancellationToken).ConfigureAwait(false)
            ?? throw new InvalidOperationException("Unable to resolve the current SQL Server database name.");
        await ExecuteNonQueryAsync(connection, $"BACKUP DATABASE {QuoteSqlServerIdentifier(databaseName)} TO DISK = N'{EscapeSqlLiteral(options.BackupPath!)}' WITH COPY_ONLY, INIT, CHECKSUM;", cancellationToken).ConfigureAwait(false);

        if (targetEncrypted)
        {
            var certificateName = runtimeOptions.EncryptionOptions.SqlServerCertificateName;
            if (string.IsNullOrWhiteSpace(certificateName))
            {
                throw new InvalidOperationException("SQL Server enable transitions require Mcp:Database:Encryption:SqlServer:CertificateName or MCP_SQLSERVER_TDE_CERTIFICATE.");
            }

            var certificateExists = await ExecuteScalarAsync<int>(connection, $"SELECT COUNT(*) FROM master.sys.certificates WHERE name = N'{EscapeSqlLiteral(certificateName)}';", cancellationToken).ConfigureAwait(false);
            if (certificateExists <= 0)
            {
                throw new InvalidOperationException($"SQL Server certificate '{certificateName}' was not found in master.sys.certificates. Provision the certificate before enabling TDE.");
            }

            var dekExists = await ExecuteScalarAsync<int>(connection, "SELECT COUNT(*) FROM sys.dm_database_encryption_keys WHERE database_id = DB_ID();", cancellationToken).ConfigureAwait(false) > 0;
            if (!dekExists)
            {
                await ExecuteNonQueryAsync(connection, $"CREATE DATABASE ENCRYPTION KEY WITH ALGORITHM = AES_256 ENCRYPTION BY SERVER CERTIFICATE {QuoteSqlServerIdentifier(certificateName)};", cancellationToken).ConfigureAwait(false);
            }

            await ExecuteNonQueryAsync(connection, $"ALTER DATABASE {QuoteSqlServerIdentifier(databaseName)} SET ENCRYPTION ON;", cancellationToken).ConfigureAwait(false);
            await WaitForSqlServerEncryptionStateAsync(connection, static state => state == 3, options.SqlServerTimeout, cancellationToken).ConfigureAwait(false);
        }
        else
        {
            await ExecuteNonQueryAsync(connection, $"ALTER DATABASE {QuoteSqlServerIdentifier(databaseName)} SET ENCRYPTION OFF;", cancellationToken).ConfigureAwait(false);
            await WaitForSqlServerEncryptionStateAsync(connection, static state => state is null or 1, options.SqlServerTimeout, cancellationToken).ConfigureAwait(false);
        }

        await ValidateAgainstTargetStateAsync(runtimeOptions, targetEncrypted, cancellationToken).ConfigureAwait(false);
        SetAllStepStatuses(report, "completed");
        report.Summary = targetEncrypted
            ? "SQL Server TDE was enabled successfully. Keep the database backup and retain all certificates and keys until the encrypted configuration is stable."
            : "SQL Server TDE was disabled successfully. Keep the database backup and retain the historical TDE certificates and keys for backup-restore compatibility.";
    }

private static async Task ExecuteNonQueryAsync(
        DbConnection connection,
        string sql,
        CancellationToken cancellationToken)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = sql;
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

private static async Task BackupAsync(DbConnection connection, string path, CancellationToken ct, string backupConnectionSettings)
    {
        if (connection is SqliteConnection sqlite)
        {
            path = Path.GetFullPath(path);
            using (new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { }
            var settings = new SqliteConnectionStringBuilder(sqlite.ConnectionString)
            {
                DataSource = path, Mode = SqliteOpenMode.ReadWrite, Pooling = false
            };
            await using var backup = new SqliteConnection(settings.ConnectionString);
            await backup.OpenAsync(ct).ConfigureAwait(false);
            sqlite.BackupDatabase(backup);
            var integrity = await RowsAsync(backup, null, "PRAGMA integrity_check", ct).ConfigureAwait(false);
            if (integrity.Count != 1 || Text(integrity[0][0]) != "ok")
                throw new InvalidOperationException("Backup verification failed; no data was changed.");
            return;
        }
        // Provider-native backup is deliberately required; a supplied old file is not proof of a backup.
        if (connection.GetType().Name == "SqlConnection")
        {
            await using var check = connection.CreateCommand();
            check.CommandText = "EXEC master.dbo.xp_fileexist @path";
            Add(check, "@path", path);
            if (Convert.ToInt32(await check.ExecuteScalarAsync(ct).ConfigureAwait(false)) != 0)
                throw new InvalidOperationException("Backup target already exists.");
            await using var command = connection.CreateCommand();
            command.CommandTimeout = 600;
            Add(command, "@path", path);
            command.CommandText = $"BACKUP DATABASE {Quote(connection.Database)} TO DISK=@path WITH COPY_ONLY,CHECKSUM";
            await command.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
            command.CommandText = "RESTORE VERIFYONLY FROM DISK=@path WITH CHECKSUM";
            await command.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
            return;
        }
        if (connection is Npgsql.NpgsqlConnection postgres)
        {
            path = Path.GetFullPath(path);
            using (new FileStream(path, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { }
            var settings = new Npgsql.NpgsqlConnectionStringBuilder(backupConnectionSettings);
            var environment = new Dictionary<string, string>
            {
                ["PGDATABASE"] = postgres.Database,
                ["PGHOST"] = settings.Host ?? "localhost",
                ["PGPORT"] = settings.Port.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ["PGUSER"] = settings.Username ?? "",
                ["PGPASSWORD"] = settings.Password ?? "",
                ["PGSSLMODE"] = settings.SslMode switch { Npgsql.SslMode.VerifyCA => "verify-ca", Npgsql.SslMode.VerifyFull => "verify-full", _ => settings.SslMode.ToString().ToLowerInvariant() },
            };
            await RunBackupToolAsync("pg_dump", ["--no-password", "--format=custom", "--file", path], environment, ct).ConfigureAwait(false);
            await RunBackupToolAsync("pg_restore", ["--list", path], environment, ct).ConfigureAwait(false);
            await using var verified = File.OpenRead(path);
            var signature = new byte[5];
            await verified.ReadExactlyAsync(signature, ct).ConfigureAwait(false);
            if (!signature.AsSpan().SequenceEqual("PGDMP"u8))
                throw new InvalidOperationException("PostgreSQL backup verification failed.");
            return;
        }
        throw new NotSupportedException("Unsupported rekey database provider.");
    }

public static async Task<Report> RunAsync(DbConnection connection, bool dryRun, string? backupPath, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var backupConnectionSettings = connection.ConnectionString;
        if (connection.State != ConnectionState.Open)
            await connection.OpenAsync(cancellationToken).ConfigureAwait(false);
        var tables = await InventoryAsync(connection, null, cancellationToken).ConfigureAwait(false);
        var plan = await PlanAsync(connection, null, tables, cancellationToken).ConfigureAwait(false);
        if (dryRun) return new(true, 0, plan.Mappings, plan.Tables, plan.Manual);
        if (string.IsNullOrWhiteSpace(backupPath))
            throw new InvalidOperationException("Apply requires --backup-path and a successful verified backup.");
        await BackupAsync(connection, backupPath, cancellationToken, backupConnectionSettings).ConfigureAwait(false);
        await using var transaction = await connection.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken).ConfigureAwait(false);
        try
        {
            // Replan under the transaction: no update uses a stale preflight.
            plan = await PlanAsync(connection, transaction, tables, cancellationToken).ConfigureAwait(false);
            var restore = await DeferConstraintsAsync(connection, transaction, tables, cancellationToken).ConfigureAwait(false);
            long changed = 0;
            foreach (var change in plan.Changes)
            {
                foreach (var batch in change.Values.Where(x => x.Key != x.Value).Chunk(200))
                {
                    await using var command = connection.CreateCommand();
                    command.Transaction = transaction;
                    command.CommandTimeout = 600;
                    var arms = new List<string>();
                    var keys = new List<string>();
                    for (var i = 0; i < batch.Length; i++)
                    {
                        Add(command, "@o" + i, batch[i].Key);
                        Add(command, "@n" + i, batch[i].Value);
                        arms.Add($"WHEN @o{i} THEN @n{i}");
                        keys.Add("@o" + i);
                    }
                    command.CommandText = $"UPDATE {change.Table.Sql} SET {Quote(change.Column)} = CASE {Exact(connection, change.Column)} "
                        + string.Join(" ", arms) + $" ELSE {Quote(change.Column)} END WHERE {Exact(connection, change.Column)} IN ({string.Join(",", keys)})";
                    changed += await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
                }
            }
            foreach (var sql in restore)
                await ExecuteAsync(connection, transaction, sql, cancellationToken).ConfigureAwait(false);
            if (connection is SqliteConnection)
            {
                var violations = await RowsAsync(connection, transaction, "PRAGMA foreign_key_check", cancellationToken).ConfigureAwait(false);
                if (violations.Count != 0) throw new InvalidOperationException("Rekey foreign-key validation failed.");
            }
            var after = await PlanAsync(connection, transaction, tables, cancellationToken).ConfigureAwait(false);
            if (after.Changes.Any(x => x.Values.Any(v => v.Key != v.Value)))
                throw new InvalidOperationException("Rekey validation found remaining noncanonical identities.");
            for (var i = 0; i < plan.Tables.Count; i++)
            {
                if (plan.Tables[i].Before != after.Tables[i].Before)
                    throw new InvalidOperationException("Rekey changed a table row count.");
                var expected = plan.Tables[i].Workspaces.ToDictionary(
                    x => plan.Mappings.FirstOrDefault(m => m.OldKey == x.Key)?.NewKey ?? x.Key, x => x.Value, StringComparer.Ordinal);
                if (expected.Count != after.Tables[i].Workspaces.Count
                    || expected.Any(x => !after.Tables[i].Workspaces.TryGetValue(x.Key, out var count) || count != x.Value))
                    throw new InvalidOperationException("Rekey changed a per-workspace row count.");
            }
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
            return new(false, changed, plan.Mappings, plan.Tables, plan.Manual);
        }
        catch
        {
            await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
            throw;
        }
    }

private static async Task ExecuteAsync(DbConnection connection, DbTransaction transaction, string sql, CancellationToken ct)
    {
        await using var command = connection.CreateCommand();
        command.Transaction = transaction;
        command.CommandText = sql;
        command.CommandTimeout = 600;
        await command.ExecuteNonQueryAsync(ct).ConfigureAwait(false);
    }

public async Task<Result<ProductDto>> HandleAsync(AddProductMemberCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);

        try
        {
            var caller = ProductCqrsHelpers.ResolveCaller(command.WorkspacePath);
            var keyError = ProductCqrsHelpers.ValidateKey(command.ProductKey, out var key);
            if (keyError is not null)
                return Result<ProductDto>.Failure(keyError);

            var memberId = WorkspaceIdentity.CanonicalizeWorkspaceId((command.MemberWorkspaceId ?? string.Empty).Trim());
            if (memberId.Length == 0)
                return Result<ProductDto>.Failure(ProductResultCodes.BadRequestMsg("Member workspace id is required."));

            var product = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            var auth = ProductCqrsHelpers.RequireOwner(db, product, caller);
            if (auth is not null)
                return Result<ProductDto>.Failure(auth);

            var workspaceError = await ProductCqrsHelpers
                .RequireRegisteredEnabledWorkspaceAsync(db, memberId, context.CancellationToken)
                .ConfigureAwait(false);
            if (workspaceError is not null)
                return Result<ProductDto>.Failure(workspaceError);

            var existing = product!.Memberships.FirstOrDefault(m =>
                string.Equals(m.WorkspaceId, memberId, StringComparison.OrdinalIgnoreCase));
            if (existing is null)
            {
                var hidden = await db.ProductWorkspaceMemberships
                    .IgnoreQueryFilters()
                    .FirstOrDefaultAsync(
                        m => m.ProductId == product.ProductId && m.WorkspaceId == memberId,
                        context.CancellationToken)
                    .ConfigureAwait(false);
                if (hidden is not null)
                {
                    ProductCqrsHelpers.ClearSoftDelete(db, hidden);
                    hidden.Role = ProductCqrsHelpers.RoleMember;
                    hidden.AddedAtUtc = DateTimeOffset.UtcNow;
                    hidden.AddedBy = caller;
                    product.Memberships.Add(hidden);
                }
                else
                {
                    product.Memberships.Add(new ProductWorkspaceMembershipEntity
                    {
                        ProductId = product.ProductId,
                        WorkspaceId = memberId,
                        Role = ProductCqrsHelpers.RoleMember,
                        AddedAtUtc = DateTimeOffset.UtcNow,
                        AddedBy = caller,
                    });
                }
            }

            product.UpdatedAtUtc = DateTimeOffset.UtcNow;
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);
            var reloaded = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            return Result<ProductDto>.Success(ProductCqrsHelpers.ToDto(db, reloaded!));
        }
        catch (Exception ex)
        {
            return Result<ProductDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<ProductDto>> HandleAsync(CreateProductCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var caller = ProductCqrsHelpers.ResolveCaller(command.WorkspacePath);
            var keyError = ProductCqrsHelpers.ValidateKey(command.Request.Key, out var key);
            if (keyError is not null)
                return Result<ProductDto>.Failure(keyError);

            var nameError = ProductCqrsHelpers.ValidateName(command.Request.Name, out var name);
            if (nameError is not null)
                return Result<ProductDto>.Failure(nameError);

            var workspaceError = await ProductCqrsHelpers
                .RequireRegisteredEnabledWorkspaceAsync(db, caller, context.CancellationToken)
                .ConfigureAwait(false);
            if (workspaceError is not null)
                return Result<ProductDto>.Failure(workspaceError);

            var existing = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            if (existing is not null)
                return Result<ProductDto>.Failure(ProductResultCodes.ConflictMsg("Product key already exists."));

            var now = DateTimeOffset.UtcNow;
            var product = new ProductEntity
            {
                Key = key,
                Name = name,
                Description = string.IsNullOrWhiteSpace(command.Request.Description)
                    ? null
                    : command.Request.Description.Trim(),
                OwnerWorkspaceId = caller,
                CreatedAtUtc = now,
                UpdatedAtUtc = now,
            };
            product.Memberships.Add(new ProductWorkspaceMembershipEntity
            {
                WorkspaceId = caller,
                Role = ProductCqrsHelpers.RoleOwner,
                AddedAtUtc = now,
                AddedBy = caller,
            });

            db.Products.Add(product);
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);
            return Result<ProductDto>.Success(ProductCqrsHelpers.ToDto(db, product));
        }
        catch (Exception ex)
        {
            return Result<ProductDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<ProductDto>> HandleAsync(DeleteProductCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);

        try
        {
            var caller = ProductCqrsHelpers.ResolveCaller(command.WorkspacePath);
            var keyError = ProductCqrsHelpers.ValidateKey(command.ProductKey, out var key);
            if (keyError is not null)
                return Result<ProductDto>.Failure(keyError);

            var product = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            var auth = ProductCqrsHelpers.RequireOwner(db, product, caller);
            if (auth is not null)
                return Result<ProductDto>.Failure(auth);

            var dto = ProductCqrsHelpers.ToDto(db, product!);
            foreach (var membership in product!.Memberships.ToList())
                db.ProductWorkspaceMemberships.Remove(membership);

            db.Products.Remove(product);
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);
            return Result<ProductDto>.Success(dto);
        }
        catch (Exception ex)
        {
            return Result<ProductDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<ProductDto>> HandleAsync(RemoveProductMemberCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);

        try
        {
            var caller = ProductCqrsHelpers.ResolveCaller(command.WorkspacePath);
            var keyError = ProductCqrsHelpers.ValidateKey(command.ProductKey, out var key);
            if (keyError is not null)
                return Result<ProductDto>.Failure(keyError);

            var target = WorkspaceIdentity.CanonicalizeWorkspaceId((command.MemberWorkspaceId ?? string.Empty).Trim());
            if (target.Length == 0)
                return Result<ProductDto>.Failure(ProductResultCodes.BadRequestMsg("Member workspace id is required."));

            var product = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            var visible = ProductCqrsHelpers.RequireVisible(db, product, caller);
            if (visible is not null)
                return Result<ProductDto>.Failure(visible);

            var isOwner = ProductCqrsHelpers.IsOwner(product!, caller);
            var isSelfLeave = string.Equals(caller, target, StringComparison.OrdinalIgnoreCase);
            if (!isOwner && !isSelfLeave)
                return Result<ProductDto>.Failure(ProductResultCodes.ForbiddenMsg("A member may leave only itself."));

            if (isOwner && isSelfLeave)
                return Result<ProductDto>.Failure(ProductResultCodes.ForbiddenMsg("Owner cannot leave; delete the product instead."));

            var membership = product!.Memberships.FirstOrDefault(m =>
                string.Equals(m.WorkspaceId, target, StringComparison.OrdinalIgnoreCase));
            if (membership is null)
                return Result<ProductDto>.Failure(ProductResultCodes.NotFoundMsg("Membership was not found."));

            db.ProductWorkspaceMemberships.Remove(membership);
            product.UpdatedAtUtc = DateTimeOffset.UtcNow;
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);

            var reloaded = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            return Result<ProductDto>.Success(ProductCqrsHelpers.ToDto(db, reloaded!));
        }
        catch (Exception ex)
        {
            return Result<ProductDto>.Failure(ex.Message, ex);
        }
    }

public async Task<Result<ProductDto>> HandleAsync(UpdateProductCommand command, CallContext context)
    {
        ArgumentNullException.ThrowIfNull(command);
        ArgumentNullException.ThrowIfNull(command.Request);

        try
        {
            var caller = ProductCqrsHelpers.ResolveCaller(command.WorkspacePath);
            var keyError = ProductCqrsHelpers.ValidateKey(command.ProductKey, out var key);
            if (keyError is not null)
                return Result<ProductDto>.Failure(keyError);

            var nameError = ProductCqrsHelpers.ValidateName(command.Request.Name, out var name);
            if (nameError is not null)
                return Result<ProductDto>.Failure(nameError);

            var product = await ProductCqrsHelpers
                .LoadProductByKeyAsync(db, key, context.CancellationToken)
                .ConfigureAwait(false);
            var auth = ProductCqrsHelpers.RequireOwner(db, product, caller);
            if (auth is not null)
                return Result<ProductDto>.Failure(auth);

            product!.Name = name;
            product.Description = string.IsNullOrWhiteSpace(command.Request.Description)
                ? null
                : command.Request.Description.Trim();
            product.UpdatedAtUtc = DateTimeOffset.UtcNow;
            await db.SaveChangesAsync(context.CancellationToken).ConfigureAwait(false);
            return Result<ProductDto>.Success(ProductCqrsHelpers.ToDto(db, product));
        }
        catch (Exception ex)
        {
            return Result<ProductDto>.Failure(ex.Message, ex);
        }
    }

private void ApplyItems(NormalizedPayload payload, Dictionary<string, RequirementEntity> existing, string timestamp)
    {
        foreach (var item in payload.Items)
        {
            var mapKey = MapKey(item.Kind, item.Id);
            if (existing.TryGetValue(mapKey, out var row))
            {
                var wasDeleted = IsSoftDeleted(row);
                row.Title = item.Title;
                row.Body = item.Body;
                row.Priority = item.Priority;
                row.Status = item.Status;
                row.UpdatedAtUtc = timestamp;
                // Ordinary create path revives soft-deleted rows by clearing deletion metadata.
                // Always clear: tracked stale shadow values must not leave IsDeleted=1 in the store.
                if (wasDeleted)
                    row.CreatedAtUtc = timestamp;
                ClearSoftDelete(row);

                continue;
            }

            _db.Requirements.Add(new RequirementEntity
            {
                WorkspaceId = payload.WorkspaceId,
                Kind = item.Kind,
                Id = item.Id,
                Title = item.Title,
                Body = item.Body,
                Priority = item.Priority,
                Status = item.Status,
                // FR-MCP-REQRECOVERY-001 / RequirementEntity default: recovery creates rows at the
                // product-requirements root layer. Item request has no ScopeStartLayerKey field.
                ScopeStartLayerKey = "layer-1",
                CreatedAtUtc = timestamp,
                UpdatedAtUtc = timestamp,
            });
        }
    }

private static RequirementsRecoveryResult Deserialize(RequirementsRecoveryRunEntity run)
    {
        var result = JsonSerializer.Deserialize<RequirementsRecoveryResult>(run.ResultJson, ResultJsonOptions)
            ?? throw new InvalidOperationException("Stored requirements recovery result is empty.");
        result.IdempotencyKey = run.IdempotencyKey;
        result.PayloadHash = run.PayloadHash;
        result.Status = run.Status;
        result.Applied = true;
        result.CreatedAtUtc = run.CreatedAtUtc;
        return result;
    }

public async Task<RequirementsRecoveryResult> ApplyAsync(RequirementsRecoveryRequest request, CancellationToken cancellationToken = default)
    {
        var payload = Validate(request);
        var prior = await FindRunAsync(payload.WorkspaceId, payload.Key, cancellationToken).ConfigureAwait(false);
        if (prior is not null)
            return ResolveExisting(prior, payload.Hash);

        // Recovery is upsert. Unique races on the requirement PK (concurrent applies with
        // different idempotency keys) reload and retry instead of fabricating an
        // idempotency-key payload conflict. Unique races on the recovery-run key still
        // resolve to Replay / Conflict via FindRunAsync.
        for (var attempt = 1; attempt <= UniqueRaceMaxAttempts; attempt++)
        {
            await using var transaction = await _db.Database
                .BeginTransactionAsync(System.Data.IsolationLevel.Serializable, cancellationToken)
                .ConfigureAwait(false);
            try
            {
                var raced = await FindRunAsync(payload.WorkspaceId, payload.Key, cancellationToken).ConfigureAwait(false);
                if (raced is not null)
                {
                    await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
                    _db.ChangeTracker.Clear();
                    return ResolveExisting(raced, payload.Hash);
                }

                var existing = await LoadExistingAsync(payload.Items, cancellationToken).ConfigureAwait(false);
                RejectAcceptanceCriteriaRemoval(payload.Items, existing);
                var createdAt = DateTimeOffset.UtcNow.ToString("o");
                var result = BuildResult(payload, existing, applied: true, replay: false, createdAtUtc: createdAt);
                ApplyItems(payload, existing, createdAt);
                _db.RequirementsRecoveryRuns.Add(new RequirementsRecoveryRunEntity
                {
                    WorkspaceId = payload.WorkspaceId,
                    IdempotencyKey = payload.Key,
                    PayloadHash = payload.Hash,
                    Status = "applied",
                    ResultJson = JsonSerializer.Serialize(result, ResultJsonOptions),
                    CreatedAtUtc = createdAt,
                });

                await StorageCommandBudget.ExecuteAsync(
                    ct => _db.SaveChangesAsync(ct),
                    cancellationToken,
                    _commandBudget).ConfigureAwait(false);
                await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
                return result;
            }
            catch (DbUpdateException ex) when (IsUniqueViolation(ex))
            {
                if (_db.Database.CurrentTransaction is not null)
                    await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
                _db.ChangeTracker.Clear();
                var raced = await FindRunAsync(payload.WorkspaceId, payload.Key, cancellationToken).ConfigureAwait(false);
                if (raced is not null)
                    return ResolveExisting(raced, payload.Hash);

                if (attempt < UniqueRaceMaxAttempts)
                    continue;

                // Preserve the actual unique failure rather than fabricating a same-key payload conflict.
                throw;
            }
            catch
            {
                if (_db.Database.CurrentTransaction is not null)
                    await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);
                throw;
            }
        }

        throw new InvalidOperationException("Requirements recovery apply exhausted unique-race retries.");
    }

public async Task<string?> AdmitAsync(BrainSlotDefinitionEntity slot, string output, string transactionId, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(slot);
        if (!string.Equals(slot.Role, BrainSlotRoles.CuriosityEngine, StringComparison.Ordinal))
            throw new BrainSlotValidationException(
                "Only CuriosityEngine committed output may be admitted to GraphRAG/context in this slice.",
                BrainSlotReasonCodes.DeferredFeatureDisabled);

        if (string.IsNullOrWhiteSpace(output))
            return null;

        var documentId = $"brain-slot-{slot.SlotId}-{Guid.NewGuid():N}";
        var sourceKey = $"{slot.Role}:{slot.SlotId}:{transactionId}";
        var chunks = _chunker.Chunk(documentId, output);
        var contentHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(output))).ToLowerInvariant();

        _db.Documents.Add(new ContextDocumentEntity
        {
            Id = documentId,
            SourceType = "brain-slot-curiosity",
            SourceKey = sourceKey,
            IngestedAt = DateTime.UtcNow,
            ContentHash = contentHash,
        });

        foreach (var chunk in chunks)
        {
            var embedding = _embeddingService.GenerateEmbedding(chunk.Content);
            _db.Chunks.Add(new ContextChunkEntity
            {
                Id = chunk.Id,
                DocumentId = documentId,
                Content = chunk.Content,
                TokenCount = chunk.TokenCount,
                ChunkIndex = chunk.ChunkIndex,
                Embedding = EmbeddingToBytes(embedding),
            });
            _vectorIndexService.AddVector(chunk.Id, embedding);
        }

        _db.DataAuditLogs.Add(new DataAuditLogEntity
        {
            WorkspaceId = _db.CurrentWorkspaceId,
            EntityKind = "BrainSlotContextAdmission",
            EntityKey = documentId,
            Action = "admit",
            SourceType = nameof(BrainSlotContextAdmissionService),
            Actor = "system",
            OccurredAtUtc = DateTimeOffset.UtcNow,
            MetadataJson = System.Text.Json.JsonSerializer.Serialize(new
            {
                slot.SlotId,
                slot.Role,
                transactionId,
                chunkCount = chunks.Count,
            }),
        });

        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        _logger.LogInformation("Brain slot Curiosity output admitted to context: {DocumentId}", documentId);
        return documentId;
    }

private async Task<BrainSlotInvokeResponse> RejectAsync(
        BrainSlotInvocationEntity invocation,
        string reason,
        DateTimeOffset started,
        string? details,
        CancellationToken cancellationToken)
    {
        invocation.Status = "rejected";
        invocation.Reason = reason;
        invocation.CompletedAtUtc = DateTimeOffset.UtcNow;
        if (_db.Entry(invocation).State == Microsoft.EntityFrameworkCore.EntityState.Detached)
        {
            if (!string.IsNullOrWhiteSpace(invocation.Role))
                _db.BrainSlotInvocations.Add(invocation);
        }
        else
        {
            _db.BrainSlotInvocations.Update(invocation);
        }

        _db.DataAuditLogs.Add(new DataAuditLogEntity
        {
            WorkspaceId = _db.CurrentWorkspaceId,
            EntityKind = "BrainSlotInvocation",
            EntityKey = invocation.InvocationId,
            Action = "invoke_rejected",
            SourceType = nameof(BrainSlotInvocationService),
            Actor = "system",
            OccurredAtUtc = DateTimeOffset.UtcNow,
            MetadataJson = JsonSerializer.Serialize(new { reason, details }),
        });
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        return new BrainSlotInvokeResponse
        {
            Status = "rejected",
            Reason = reason,
            SlotId = invocation.SlotId,
            Role = invocation.Role,
            TransactionId = invocation.TransactionId,
            DiffgramId = invocation.DiffgramId,
            ModelId = string.IsNullOrWhiteSpace(invocation.ModelId) ? null : invocation.ModelId,
            Output = null,
            StartedAtUtc = started,
            CompletedAtUtc = invocation.CompletedAtUtc ?? DateTimeOffset.UtcNow,
        };
    }

public async Task<BrainSlotInvokeResponse> InvokeAsync(string slotId, BrainSlotInvokeRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        var started = DateTimeOffset.UtcNow;
        var normalizedSlotId = string.IsNullOrWhiteSpace(slotId) ? string.Empty : slotId.Trim();
        var invocation = new BrainSlotInvocationEntity
        {
            SlotId = normalizedSlotId,
            Status = "attempted",
            Reason = BrainSlotReasonCodes.None,
            TurnId = request.TurnId,
            StartedAtUtc = started,
            AdmitToGraphRag = request.AdmitToGraphRag,
            MetadataJson = JsonSerializer.Serialize(request.Metadata ?? new Dictionary<string, string>()),
        };

        var slot = await _registry.GetEntityAsync(normalizedSlotId, cancellationToken).ConfigureAwait(false);
        if (slot is null)
            return await RejectAsync(invocation, BrainSlotReasonCodes.SlotNotFound, started, "slot not found", cancellationToken).ConfigureAwait(false);

        PopulateInvocationFromSlot(invocation, slot);
        _db.BrainSlotInvocations.Add(invocation);
        AddAudit("invoke_attempt", slot, invocation, null);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        if (!_brainSlotOptions.CurrentValue.ExecutionEnabled)
            return await RejectAsync(invocation, BrainSlotReasonCodes.ExecutionDisabled, started, "execution disabled", cancellationToken).ConfigureAwait(false);
        if (!slot.Enabled)
            return await RejectAsync(invocation, BrainSlotReasonCodes.SlotDisabled, started, "slot disabled", cancellationToken).ConfigureAwait(false);
        if (string.IsNullOrWhiteSpace(request.Input))
            return await RejectAsync(invocation, BrainSlotReasonCodes.ValidationFailed, started, "input is required", cancellationToken).ConfigureAwait(false);
        if (request.AdmitToGraphRag && !string.Equals(slot.Role, BrainSlotRoles.CuriosityEngine, StringComparison.Ordinal))
            return await RejectAsync(invocation, BrainSlotReasonCodes.DeferredFeatureDisabled, started, "only CuriosityEngine may request GraphRAG admission", cancellationToken).ConfigureAwait(false);
        if (!TransactionsAreRequired())
            return await RejectAsync(invocation, BrainSlotReasonCodes.TransactionsRequired, started, "required turn transactions are disabled", cancellationToken).ConfigureAwait(false);

        try
        {
            BrainSlotValidation.ValidateEndpoint(slot.ProviderKind, slot.Endpoint, _brainSlotOptions);
        }
        catch (BrainSlotValidationException ex)
        {
            return await RejectAsync(invocation, ex.Reason, started, ex.Message, cancellationToken).ConfigureAwait(false);
        }

        if (!await PartyMappingIsActiveAsync(slot, cancellationToken).ConfigureAwait(false))
            return await RejectAsync(invocation, BrainSlotReasonCodes.PartyMappingInvalid, started, "trusted party signing key is missing or disabled", cancellationToken).ConfigureAwait(false);

        var credential = await _credentialResolver.ResolveAsync(slot.CredentialReference, cancellationToken).ConfigureAwait(false);
        if (credential is null)
            return await RejectAsync(invocation, BrainSlotReasonCodes.CredentialUnavailable, started, "credential reference could not be resolved", cancellationToken).ConfigureAwait(false);

        var promptHash = HashHex(request.Input);
        invocation.PromptSha256 = promptHash;
        string output;
        try
        {
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            timeoutCts.CancelAfter(TimeSpan.FromSeconds(slot.TimeoutSeconds <= 0 ? _brainSlotOptions.CurrentValue.DefaultTimeoutSeconds : slot.TimeoutSeconds));
            var turnContext = request.TurnContext ?? BrainSlotTurnContext.FromInvokeRequest(request);
            var strategy = _chatClientFactory.CreateStrategy(slot, credential);
            output = await strategy.CompleteAsync(slot, request.Input, turnContext, request.Temperature, timeoutCts.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            return await RejectAsync(invocation, BrainSlotReasonCodes.ProviderFailed, started, "provider timeout", cancellationToken).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not OperationCanceledException || !cancellationToken.IsCancellationRequested)
        {
            _logger.LogWarning(ex, "Brain slot provider failed for {SlotId}", slot.SlotId);
            return await RejectAsync(invocation, BrainSlotReasonCodes.ProviderFailed, started, "provider failed", cancellationToken).ConfigureAwait(false);
        }

        var outputHash = HashHex(output);
        invocation.OutputSha256 = outputHash;
        var operationBodyJson = JsonSerializer.Serialize(new
        {
            slotId = slot.SlotId,
            slot.Role,
            slot.ProviderKind,
            slot.ModelId,
            promptSha256 = promptHash,
            outputSha256 = outputHash,
            admissionTarget = request.AdmitToGraphRag ? "GraphRAG" : "none",
            temperature = request.Temperature,
            metadata = request.Metadata,
            startedAtUtc = started,
            modelCompletedAtUtc = DateTimeOffset.UtcNow,
        });

        var transaction = await _transactionCoordinator!.ExecuteAsync(
            new TurnTransactionRequest
            {
                TransactionId = $"brain-slot-{Guid.NewGuid():N}",
                TurnId = request.TurnId,
                OperationName = "brain-slot.invoke",
                OperationBodyJson = operationBodyJson,
                PublisherPartyId = slot.PartyId,
                Sequence = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                Mutating = true,
            },
            _ => Task.FromResult(new TurnMutationResult
            {
                Success = true,
                ResultJson = JsonSerializer.Serialize(new
                {
                    slot.SlotId,
                    slot.Role,
                    slot.ModelId,
                    promptSha256 = promptHash,
                    outputSha256 = outputHash,
                }),
            }),
            cancellationToken).ConfigureAwait(false);

        if (!string.Equals(transaction.Status, "committed", StringComparison.OrdinalIgnoreCase))
        {
            invocation.TransactionId = transaction.TransactionId;
            return await RejectAsync(invocation, BrainSlotReasonCodes.CommitFailed, started, transaction.Message ?? transaction.Status, cancellationToken).ConfigureAwait(false);
        }

        invocation.Status = "committed";
        invocation.Reason = BrainSlotReasonCodes.None;
        invocation.TransactionId = transaction.TransactionId;
        invocation.DiffgramId = transaction.DiffgramId;
        invocation.CompletedAtUtc = DateTimeOffset.UtcNow;
        AddAudit("invoke_committed", slot, invocation, new { transaction.TransactionId, transaction.DiffgramId });
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);

        if (request.AdmitToGraphRag && string.Equals(slot.Role, BrainSlotRoles.CuriosityEngine, StringComparison.Ordinal))
        {
            try
            {
                await _contextAdmission.AdmitAsync(slot, output, transaction.TransactionId, cancellationToken).ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is not OperationCanceledException || !cancellationToken.IsCancellationRequested)
            {
                _logger.LogWarning(ex, "Committed brain-slot output admission failed for {SlotId}", slot.SlotId);
            }
        }

        return new BrainSlotInvokeResponse
        {
            Status = "committed",
            Reason = BrainSlotReasonCodes.None,
            SlotId = slot.SlotId,
            Role = slot.Role,
            TransactionId = transaction.TransactionId,
            DiffgramId = transaction.DiffgramId,
            ModelId = slot.ModelId,
            Output = output,
            StartedAtUtc = started,
            CompletedAtUtc = invocation.CompletedAtUtc ?? DateTimeOffset.UtcNow,
        };
    }

public async Task<BrainSlotDto> DeleteAsync(string slotId, CancellationToken cancellationToken = default)
    {
        var entity = await GetRequiredEntityAsync(slotId, cancellationToken).ConfigureAwait(false);
        entity.Enabled = false;
        entity.UpdatedAtUtc = DateTimeOffset.UtcNow;
        var dto = ToDto(entity);
        AddAudit("delete", entity, null);
        _db.BrainSlotDefinitions.Remove(entity);
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return dto;
    }

public async Task<BrainSlotDto> EnableAsync(string slotId, bool replaceExisting, CancellationToken cancellationToken = default)
    {
        var entity = await GetRequiredEntityAsync(slotId, cancellationToken).ConfigureAwait(false);
        await EnforceEnabledRoleUniquenessAsync(entity.SlotId, entity.Role, replaceExisting, cancellationToken).ConfigureAwait(false);
        entity.Enabled = true;
        entity.UpdatedAtUtc = DateTimeOffset.UtcNow;
        await RegisterPartyAsync(entity, cancellationToken).ConfigureAwait(false);
        AddAudit("enable", entity, new { replaceExisting });
        await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
        return ToDto(entity);
    }

