                SET "Status" = {"in_progress"},
                    "UpdatedAtUtc" = {now}
                WHERE "OperationId" = {operationId}
                  AND (
                      "Status" = {"pending"}
                      OR ("Status" = {"in_progress"} AND "UpdatedAtUtc" <= {staleInProgressBeforeUtc})
