            return null;

        var entity = await db.TransactionPubSubMessages
            .AsNoTracking()
            .SingleOrDefaultAsync(message => message.OperationId == operationId, cancellationToken)
            .ConfigureAwait(false);
        return entity is null ? null : ToState(entity);
    }

